window.WB_BOOK=window.WB_BOOK||{};window.WB_BOOK["week04"]={"id":"week04","n":4,"section":"A","label":"","title":"Energy, Power & Hydrostatics","titleText":"Energy, Power & Hydrostatics","subtitle":"Work, energy changes, power, efficiency — and why things float or sink","intro":"Energy is the idea that links ALL of Physics. This week you learn what energy is, the forms it takes, how it changes from one form to another, and how we measure it with work done, potential energy and kinetic energy. You will calculate power and efficiency, and discuss the alternative energy sources that matter so much to the Caribbean. In the last two units you meet pressure in solids and liquids, and Archimedes' principle, which explains why a steel ship floats. Nearly every Paper 02 has an energy calculation (mgh and ½mv^2^) — these are some of the most reliable marks in the exam.","objectives":[{"code":"A5.1","text":"Define energy and state its SI unit, the joule (J)"},{"code":"A5.2","text":"Identify the various forms of energy"},{"code":"A5.3","text":"Describe energy transformations in everyday situations and devices"},{"code":"A5.4","text":"Define work done and use ⟪W=F\\times d⟫"},{"code":"A5.5","text":"Discuss alternative sources of energy and their importance to the Caribbean"},{"code":"A5.6","text":"Define potential energy"},{"code":"A5.7","text":"Calculate changes in gravitational potential energy using ⟪\\Delta E_{p}=mg\\Delta h⟫"},{"code":"A5.8","text":"Define kinetic energy"},{"code":"A5.9","text":"Calculate kinetic energy using ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫"},{"code":"A5.10","text":"Apply the law of conservation of energy"},{"code":"A5.11","text":"Define power and use ⟪P=E/t⟫"},{"code":"A5.12","text":"Explain efficiency and the factors that affect the efficiency of a system"},{"code":"A5.13","text":"Calculate the efficiency of energy conversions"},{"code":"A6.1","text":"Define pressure and use ⟪P=F/A⟫"},{"code":"A6.2","text":"Explain how pressure in a fluid depends on depth and use ⟪P=\\rho gh⟫"},{"code":"A6.3","text":"Apply Archimedes' principle (upthrust) to explain floating and sinking"}],"formulaCard":[{"tex":"W=F\\times d","meaning":"Work done = force × distance moved in direction of force","units":"J"},{"tex":"\\Delta E_{p}=mg\\Delta h","meaning":"Change in gravitational PE; ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫","units":"J"},{"tex":"E_{k}=\\tfrac{1}{2}mv^{2}","meaning":"Kinetic energy (square v only)","units":"J"},{"tex":"mgh=\\tfrac{1}{2}mv^{2}\\rightarrow v=\\sqrt{2gh}","meaning":"Falling with no friction: PE lost ⟪=KE⟫ gained","units":"m s^−1^"},{"tex":"P=E\\div t=W\\div t","meaning":"Power = energy converted ÷ time","units":"⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫"},{"tex":"\\text{efficiency }=\\text{ useful output }\\div \\text{ total input }\\times 100\\%","meaning":"Energy or power; always < 100%","units":"% (no unit)"},{"tex":"P=F\\div A","meaning":"Pressure = normal force ÷ area","units":"⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫"},{"tex":"P=\\rho gh","meaning":"Pressure due to a liquid at depth h","units":"Pa"},{"tex":"\\text{total pressure }=\\text{ atmospheric }+\\rho gh","meaning":"Atmospheric ≈ ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫","units":"Pa"},{"tex":"\\text{upthrust }=\\text{ weight of fluid displaced }=\\rho _{\\text{fluid}}Vg","meaning":"Archimedes' principle","units":"N"},{"text":"upthrust = weight in air − weight in liquid","meaning":"Apparent loss in weight","units":"N"},{"text":"floating: upthrust = weight","meaning":"Floats if density < fluid density","units":""},{"tex":"1\\,\\mathrm{J}=1\\,\\mathrm{N}\\,\\mathrm{m}=1\\,\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}","meaning":"Joule in base units","units":""}],"glossary":[{"term":"Energy","def":"The ability (capacity) to do work."},{"term":"Work done","def":"Force × distance moved in the direction of the force."},{"term":"Joule","def":"Work done when a 1 N force moves its point of application 1 m in the direction of the force."},{"term":"Potential energy","def":"Energy stored because of position or condition."},{"term":"Kinetic energy","def":"Energy an object has because of its motion."},{"term":"Conservation of energy","def":"Energy cannot be created or destroyed, only changed from one form to another."},{"term":"Power","def":"Rate of doing work / rate of energy conversion."},{"term":"Watt","def":"One joule per second."},{"term":"Efficiency","def":"Useful output ÷ total input, × 100%."},{"term":"Renewable source","def":"An energy source that is naturally replaced and will not run out."},{"term":"Non-renewable source","def":"A source being used up faster than it can be replaced (fossil fuels, uranium)."},{"term":"Geothermal energy","def":"Heat energy from hot rocks below the Earth's surface."},{"term":"Biomass","def":"Plant or animal material (e.g. bagasse) used as fuel."},{"term":"Pressure","def":"Force acting normally per unit area."},{"term":"Pascal","def":"One newton per square metre."},{"term":"Upthrust","def":"Upward force of a fluid on an immersed object."},{"term":"Archimedes' principle","def":"Upthrust equals the weight of fluid displaced."},{"term":"Principle of flotation","def":"A floating object displaces its own weight of fluid."},{"term":"Sankey diagram","def":"Energy-flow diagram; arrow widths show amounts of energy."}],"lessons":[{"id":"week04.4.1","kind":"unit","unit":"4.1","title":"Energy, Its Forms, Energy Changes and Work Done","titleText":"Energy, Its Forms, Energy Changes and Work Done","goals":[{"code":"A5.1","text":"Define energy and state its SI unit, the joule (J)"},{"code":"A5.2","text":"Identify the various forms of energy"},{"code":"A5.3","text":"Describe energy transformations in everyday situations and devices"},{"code":"A5.4","text":"Define work done and use ⟪W=F\\times d⟫"}],"codes":["A5.1","A5.2","A5.3","A5.4"],"words":[{"term":"Energy","def":"The ability (capacity) to do work."},{"term":"Work done","def":"Force × distance moved in the direction of the force."},{"term":"Joule","def":"Work done when a 1 N force moves its point of application 1 m in the direction of the force."},{"term":"Potential energy","def":"Energy stored because of position or condition."},{"term":"Kinetic energy","def":"Energy an object has because of its motion."},{"term":"Power","def":"Rate of doing work / rate of energy conversion."}],"learn":{"notes":[{"type":"h","text":"What is energy?"},{"type":"def","term":"Energy","text":"the ability (capacity) to do work. It is a scalar quantity. SI unit: the **joule (J)**."},{"type":"p","text":"Anything that is moving, hot, high up, stretched, lit, or able to react chemically has energy. When energy is used, it is not used up — it is **transferred** or **changed** into another form."},{"type":"h","text":"Forms of energy (A5.2)"},{"type":"table","headers":["Form","What it is","Example"],"rows":[["Kinetic (KE)","energy of a moving object","a moving car, wind, flowing river"],["Gravitational potential (GPE)","energy stored because of height (position) in a gravitational field","water in a hilltop reservoir, a coconut on the tree"],["Elastic (strain) potential","energy stored in a stretched or squashed object","stretched catapult, bow, compressed spring"],["Chemical","energy stored in the bonds of substances, released in reactions","food, fuels (gasoline, coal), batteries"],["Electrical","energy carried by an electric current","mains electricity, a battery circuit"],["Thermal (heat / internal)","energy of the random motion of particles","a hot pot, the Sun's heat"],["Light (radiant)","energy carried by light / electromagnetic waves","sunlight, a lamp"],["Sound","energy carried by vibrations of particles","a steel pan, a loudspeaker"],["Nuclear","energy stored in the nucleus of atoms","the Sun, nuclear power stations"]]},{"type":"remember","text":"**Stored** forms (potential): GPE, elastic, chemical, nuclear. **Moving / transfer** forms: kinetic, electrical, thermal, light, sound."},{"type":"h","text":"Energy transformations (A5.3)"},{"type":"p","text":"A device changes energy from one form into another. In an exam, write the **input form → output form(s)**, including the wasted forms (usually heat and sound)."},{"type":"table","headers":["Device / situation","Energy change"],"rows":[["Solar cell (PV panel)","light → electrical"],["Battery-powered torch","chemical → electrical → light + heat"],["Electric motor (fan, drill)","electrical → kinetic (+ heat + sound)"],["Generator / dynamo","kinetic → electrical"],["Loudspeaker","electrical → sound"],["Microphone","sound → electrical"],["Electric kettle / iron","electrical → thermal (heat)"],["Car engine","chemical (fuel) → kinetic + heat + sound"],["Car brakes","kinetic → heat (+ sound)"],["Photosynthesis in leaves","light → chemical"],["Falling coconut","gravitational PE → kinetic"],["Archer releasing an arrow","elastic PE → kinetic"],["Person running up stairs","chemical (food) → kinetic + GPE + heat"]]},{"type":"tip","text":"For an energy CHAIN (e.g. a hydroelectric station) write each stage with arrows: GPE of water → KE of water → KE of turbine → electrical energy. One mark is usually given per correct stage."},{"type":"h","text":"Work done (A5.4)"},{"type":"def","term":"Work done","text":"the product of a force and the distance moved in the direction of the force. Work is done whenever a force moves its point of application."},{"type":"formula","tex":"W=F\\times d","where":["⟪W⟫ = work done in joules (J)","⟪F⟫ = force in newtons (N)","⟪d⟫ = distance moved IN THE DIRECTION OF THE FORCE in metres (m)","⟪1\\,\\mathrm{J}⟫ = ⟪1\\,\\mathrm{N}\\,\\mathrm{m}=1\\,\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫"],"label":"WORK DONE"},{"type":"def","term":"The joule","text":"the work done when a force of 1 newton moves its point of application through 1 metre in the direction of the force."},{"type":"img","src":"img/week04/work_done","alt":"Figure 4.1 — (a) Work is done when the box moves in the direction of F. (b) No work is done on the bag when it is carried horizontally.","caption":"Figure 4.1 — (a) Work is done when the box moves in the direction of F. (b) No work is done on the bag when it is carried horizontally.","width":6,"w":1400,"h":372},{"type":"p","text":"**Work done = energy transferred.** When you do 300 J of work pushing a box, 300 J of energy is transferred from you (chemical energy) to the box (as kinetic energy and heat from friction)."},{"type":"h","text":"When is NO work done?"},{"type":"bullets","items":["The object does not move: pushing a wall, or holding a heavy bag still ⟪(d=0)⟫. You feel tired, but no work is done on the bag.","The force is at 90° to the motion: carrying a bag along a level corridor — your force is upward, the movement is sideways.","An object moving at constant speed with no force on it in the direction of motion (e.g. a puck sliding on smooth ice)."]},{"type":"h","text":"Work done lifting an object"},{"type":"p","text":"To lift an object at steady speed you push up with a force equal to its weight, mg. Distance moved = height h. So **work done against gravity **⟪\\boldsymbol{=mg\\times h}⟫. This work becomes gravitational potential energy (Unit 4.3)."},{"type":"warn","text":"Use the distance moved in the direction of the force. When lifting a box up a ramp, the work done against gravity uses the VERTICAL height, not the length of the ramp."}],"examples":[{"id":"week04.4.1.e1","title":"Pushing a box","question":"A boy pushes a box with a force of 50 N across a floor through a distance of 6.0 m. Calculate the work done.","steps":[{"label":"Formula","text":"⟪W=F\\times d⟫"},{"label":"Substitute","text":"⟪W=50\\times 6.0⟫"},{"label":"Answer","text":"⟪W=300\\,\\mathrm{J}⟫"}],"answer":"Work done ⟪=300\\,\\mathrm{J}⟫"},{"id":"week04.4.1.e2","title":"Lifting a box onto a shelf","question":"A 12 kg box is lifted at a steady speed onto a shelf 1.5 m above the floor. Calculate (a) the weight of the box (b) the work done.","steps":[{"label":"(a) Weight","text":"⟪W=mg=12\\times 10=120\\,\\mathrm{N}⟫"},{"label":"(b) Formula","text":"work = force × distance = weight × height"},{"label":"Substitute","text":"work ⟪=120\\times 1.5⟫"},{"label":"Answer","text":"work ⟪=180\\,\\mathrm{J}⟫"}],"answer":"(a) 120 N  (b) 180 J"},{"id":"week04.4.1.e3","title":"Finding the force","question":"A farmer does 2400 J of work pulling a cart 30 m along a level road. What force did he apply (in the direction of motion)?","steps":[{"label":"Rearrange","text":"⟪W=F\\times d\\rightarrow F=W\\div d⟫"},{"label":"Substitute","text":"⟪F=2400\\div 30⟫"},{"label":"Answer","text":"⟪F=80\\,\\mathrm{N}⟫"}],"answer":"⟪F=80\\,\\mathrm{N}⟫"}]},"tryit":[{"id":"week04.4.1.p1","kind":"self","q":"Define **energy** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"The ability/capacity to do work (1); joule, J (1).","points":[{"text":"The ability/capacity to do work","marks":1},{"text":"joule, J","marks":1}],"section":"try"},{"id":"week04.4.1.p2","kind":"self","q":"State the main energy change in: (a) a solar cell (b) a loudspeaker (c) a battery-powered torch (d) the brakes of a moving car.","marks":4,"level":3,"lines":4,"scheme":"(a) light → electrical (1) (b) electrical → sound (1) (c) chemical → electrical → light (and heat) (1) (d) kinetic → heat/thermal (and sound) (1).","points":[{"text":"(a) light → electrical","marks":1},{"text":"(b) electrical → sound","marks":1},{"text":"(c) chemical → electrical → light (and heat)","marks":1},{"text":"(d) kinetic → heat/thermal (and sound)","marks":1}],"section":"try"}],"practice":[{"id":"week04.4.1.p3","kind":"self","q":"Define the **joule**.","marks":2,"level":2,"lines":2,"scheme":"The work done when a force of 1 N (1) moves its point of application 1 m in the direction of the force (1).","points":[{"text":"The work done when a force of 1 N","marks":1},{"text":"moves its point of application 1 m in the direction of the force","marks":1}],"section":"practice"},{"id":"week04.4.1.p4","kind":"num","q":"A force of 25 N pushes a trolley through 8.0 m. Calculate the work done.","marks":2,"level":2,"lines":2,"scheme":"⟪W=F\\times d=25\\times 8.0⟫ (1) ⟪=200\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪W=F\\times d=25\\times 8.0⟫","marks":1},{"text":"⟪=200\\,\\mathrm{J}⟫","marks":1}],"num":{"value":200,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (Pushing a box). Start like this: Formula: ⟪W=F\\times d⟫","from":1}},{"id":"week04.4.1.p5","kind":"self","q":"A man holds a 20 kg suitcase still for 5 minutes. How much work does he do ON the suitcase? Explain.","marks":2,"level":2,"lines":3,"scheme":"Zero (1); the suitcase does not move, so distance moved in the direction of the force is zero ⟪(W=F\\times 0)⟫ (1).","points":[{"text":"Zero","marks":1},{"text":"the suitcase does not move, so distance moved in the direction of the force is zero ⟪(W=F\\times 0)⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Finding the force). Start like this: Rearrange: ⟪W=F\\times d\\rightarrow F=W\\div d⟫","from":3}},{"id":"week04.4.1.p6","kind":"self","q":"A crane lifts a 500 kg load through a height of 12 m. Calculate (a) the weight of the load (b) the work done by the crane.","marks":3,"level":2,"lines":3,"scheme":"(a) ⟪W=mg=500\\times 10=5000\\,\\mathrm{N}⟫ (1). (b) work ⟪=5000\\times 12⟫ (1) ⟪=60\\,000\\,\\mathrm{J}=60\\,\\mathrm{kJ}⟫ (1).","points":[{"text":"(a) ⟪W=mg=500\\times 10=5000\\,\\mathrm{N}⟫","marks":1},{"text":"(b) work ⟪=5000\\times 12⟫","marks":1},{"text":"⟪=60\\,000\\,\\mathrm{J}=60\\,\\mathrm{kJ}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Pushing a box). Start like this: Formula: ⟪W=F\\times d⟫","from":1}},{"id":"week04.4.1.p7","kind":"num","q":"4500 J of work is done pushing a stalled car 15 m. Calculate the force used.","marks":2,"level":2,"lines":2,"scheme":"⟪F=W\\div d=4500\\div 15⟫ (1) ⟪=300\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪F=W\\div d=4500\\div 15⟫","marks":1},{"text":"⟪=300\\,\\mathrm{N}⟫","marks":1}],"num":{"value":300,"sf":1,"unit":"N","unitTex":"\\mathrm{N}"},"section":"practice","hint":{"text":"Look back at Example 1 (Pushing a box). Start like this: Formula: ⟪W=F\\times d⟫","from":1}},{"id":"week04.4.1.p8","kind":"self","q":"Show that the joule can be written as kg m^2^ s^−2^ in base units.","marks":2,"level":2,"lines":3,"scheme":"⟪J=N\\times m⟫ (1); ⟪N=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫, so ⟪J=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}\\times m=\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫ (1).","points":[{"text":"⟪J=N\\times m⟫","marks":1},{"text":"⟪N=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫, so ⟪J=\\mathrm{kg}\\,\\mathrm{m}\\,\\mathrm{s}^{-2}\\times m=\\mathrm{kg}\\,\\mathrm{m}^{2}\\,\\mathrm{s}^{-2}⟫","marks":1}],"section":"practice"}],"exit":[{"id":"week04.4.1.p9","kind":"self","q":"A girl pulls a box 40 m across a rough floor at constant speed with a force of 60 N. (a) Calculate the work she does. (b) The box does not speed up. Where does the energy go?","marks":3,"level":2,"lines":4,"scheme":"(a) ⟪W=60\\times 40⟫ (1) ⟪=2400\\,\\mathrm{J}⟫ (1). (b) Work done against friction is changed into heat/thermal energy (and some sound) in the box and floor (1).","points":[{"text":"(a) ⟪W=60\\times 40⟫","marks":1},{"text":"⟪=2400\\,\\mathrm{J}⟫","marks":1},{"text":"(b) Work done against friction is changed into heat/thermal energy (and some sound) in the box and floor","marks":1}],"section":"exit"},{"id":"week04.4.1.p10","kind":"self","q":"Write the energy chain for a person using a bicycle dynamo to light a lamp.","marks":3,"level":2,"lines":3,"scheme":"Chemical energy (food) in person → kinetic energy of wheel/dynamo (1) → electrical energy (1) → light (+ heat) in the lamp (1).","points":[{"text":"Chemical energy (food) in person → kinetic energy of wheel/dynamo","marks":1},{"text":"→ electrical energy","marks":1},{"text":"→ light (+ heat) in the lamp","marks":1}],"section":"exit"}],"warmup":[{"id":"week04.4.1.w1","kind":"self","q":"What does the gradient of a velocity–time graph represent? And the area under it?","marks":1,"level":1,"scheme":"Gradient = acceleration; area = displacement (distance travelled).","points":[{"text":"Gradient = acceleration; area = displacement (distance travelled).","marks":1}],"section":"warmup","src":"week03.r1"},{"id":"week04.4.1.w2","kind":"self","q":"State Newton's first law.","marks":1,"level":1,"scheme":"A body stays at rest or in uniform motion in a straight line unless acted on by a resultant force.","points":[{"text":"A body stays at rest or in uniform motion in a straight line unless acted on by a resultant force.","marks":1}],"section":"warmup","src":"week03.r2"},{"id":"week04.4.1.w3","kind":"num","q":"A 1500 kg car has a driving force of 4000 N and resistive forces of 1000 N. Find its acceleration.","marks":1,"level":1,"scheme":"Resultant ⟪=3000\\,\\mathrm{N}⟫; ⟪a=3000\\div 1500=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫.","points":[{"text":"Resultant ⟪=3000\\,\\mathrm{N}⟫; ⟪a=3000\\div 1500=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-2}⟫.","marks":1}],"num":{"value":2,"sf":2,"unit":"m s^−2^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-2}"},"section":"warmup","src":"week03.r3"},{"id":"week04.4.1.w4","kind":"self","q":"Define momentum and give its unit.","marks":1,"level":1,"scheme":"Mass × velocity; kg m s⁻¹ (N s).","points":[{"text":"Mass × velocity; kg m s⁻¹ (N s).","marks":1}],"section":"warmup","src":"week03.r4"},{"id":"week04.4.1.w5","kind":"self","q":"A 0.020 kg bullet leaves a 5.0 kg gun at 300 m s⁻¹. Find the recoil speed of the gun.","marks":1,"level":1,"scheme":"⟪0=0.020\\times 300+5.0v\\rightarrow v=-1.2\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫, i.e. 1.2 m s⁻¹ backwards.","points":[{"text":"⟪0=0.020\\times 300+5.0v\\rightarrow v=-1.2\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫, i.e. 1.2 m s⁻¹ backwards.","marks":1}],"section":"warmup","src":"week03.r5"}],"quickStart":[{"type":"p","text":"You need these four tools from earlier weeks. Check each one before Unit 4.1."},{"type":"h","text":"1. Weight ⟪W=mg⟫ (Week 2)"},{"type":"p","text":"Weight (N) = mass ⟪(\\mathrm{kg})\\times 10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫. A 5.0 kg bag has weight ⟪5.0\\times 10=\\boldsymbol{50\\,\\mathrm{N}}⟫. You will use this in work, potential energy, pressure and upthrust questions."},{"type":"h","text":"2. Convert to SI units BEFORE you substitute"},{"type":"table","headers":["Change","How","Example"],"rows":[["g → kg","÷ 1000","⟪250\\,\\mathrm{g}=0.250\\,\\mathrm{kg}⟫"],["minutes → s","× 60","⟪3.0\\,\\mathrm{min}=180\\,\\mathrm{s}⟫"],["kJ → J","× 1000","⟪4.5\\,\\mathrm{kJ}=4500\\,\\mathrm{J}⟫"],["cm^2^ → m^2^","÷ ⟪10\\,000\\ (\\times 10^{-4})⟫","⟪50\\,\\mathrm{cm}^{2}=0.0050\\,\\mathrm{m}^{2}⟫"],["km/h → m/s","÷ 3.6","⟪72\\,\\mathrm{km}/\\mathrm{h}=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"]]},{"type":"h","text":"3. Squares and square roots"},{"type":"p","text":"In ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫ only the **v** is squared. ⟪6^{2}=36⟫, ⟪15^{2}=225⟫, ⟪20^{2}=400⟫. To undo a square, take the square root: if ⟪v^{2}=100⟫ then ⟪v=\\sqrt{100}=10⟫."},{"type":"h","text":"4. Rearranging"},{"type":"p","text":"⟪E=mgh\\rightarrow h=E\\div (mg)⟫.   ⟪P=E\\div t\\rightarrow E=P\\times t⟫ and ⟪t=E\\div P⟫.   ⟪E=\\tfrac{1}{2}mv^{2}\\rightarrow v^{2}=2E\\div m\\rightarrow v=\\sqrt{2E\\div m}⟫."},{"type":"fill","text":"Try it: make **F** the subject of ⟪W=F\\times d⟫.   F = ","lines":1},{"type":"fill","text":"Try it: make **A** the subject of ⟪P=F\\div A⟫.   A = ","lines":1}],"n":22},{"id":"week04.4.2","kind":"unit","unit":"4.2","title":"Energy Sources and the Caribbean","titleText":"Energy Sources and the Caribbean","goals":[{"code":"A5.5","text":"Discuss alternative sources of energy and their importance to the Caribbean"}],"codes":["A5.5"],"words":[{"term":"Energy","def":"The ability (capacity) to do work."},{"term":"Power","def":"Rate of doing work / rate of energy conversion."},{"term":"Renewable source","def":"An energy source that is naturally replaced and will not run out."},{"term":"Non-renewable source","def":"A source being used up faster than it can be replaced (fossil fuels, uranium)."},{"term":"Geothermal energy","def":"Heat energy from hot rocks below the Earth's surface."},{"term":"Biomass","def":"Plant or animal material (e.g. bagasse) used as fuel."}],"learn":{"notes":[{"type":"h","text":"Renewable and non-renewable sources"},{"type":"def","term":"Non-renewable energy source","text":"a source that is being used up faster than it can be replaced; once used it is gone (e.g. coal, oil, natural gas, uranium)."},{"type":"def","term":"Renewable (alternative) energy source","text":"a source that is naturally replaced and will not run out (e.g. solar, wind, hydroelectric, geothermal, biomass, wave, tidal)."},{"type":"p","text":"**Fossil fuels** (coal, oil, natural gas) formed over millions of years from the remains of dead plants and animals. Burning them releases carbon dioxide (a greenhouse gas that causes global warming) and other pollutants (sulfur dioxide → acid rain). Most Caribbean islands have no fossil fuels of their own and must **import oil**, which makes electricity very expensive. (Trinidad and Tobago is an exception — it produces its own oil and natural gas.)"},{"type":"h","text":"Alternative sources — what you must know"},{"type":"table","headers":["Source","Energy change","Advantages","Disadvantages","Caribbean example"],"rows":[["Solar (photovoltaic cells; solar water heaters)","light → electrical (PV); light → heat (water heater)","Free, plenty of sunshine all year, no pollution while working, low maintenance","No output at night; less on cloudy days; high starting cost; needs large area; storage batteries needed","Solar water heaters on many homes in Barbados; solar farms in Jamaica, Barbados, Antigua"],["Wind (wind turbines)","KE of wind → electrical","Free, no pollution, strong steady trade winds","Wind not constant; noise; visual impact; can be damaged by hurricanes","Wigton Wind Farm, Jamaica; wind farms in Aruba and Curaçao"],["Hydroelectric (dams on rivers)","GPE of water → KE → electrical","Reliable, can be switched on quickly, no pollution, water stored","Needs rivers and high land; dam floods land; expensive to build; drought reduces output","Dominica, Jamaica, Guyana and Suriname (large rivers)"],["Geothermal (hot rocks underground)","heat → KE of steam → electrical","Works day and night; no fuel cost; volcanic islands have a lot of it","Only where there is volcanic activity; drilling is expensive; may release harmful gases","Guadeloupe (Bouillante plant); Dominica, St Kitts & Nevis, St Lucia exploring"],["Biomass / biofuel (plant and animal waste)","chemical → heat → electrical","Uses waste (bagasse from sugar cane, animal manure → biogas); renewable","Burning still gives some CO~2~ and smoke; needs land and crops","Bagasse burned in sugar factories in Guyana and Jamaica"],["Wave and tidal","KE of water → electrical","Free, predictable (tides)","Caribbean tidal range is very small; damage by storms; expensive","Not widely used in the Caribbean"]]},{"type":"img","src":"img/week04/hydro","alt":"Figure 4.2 — A hydroelectric scheme and its energy changes","caption":"Figure 4.2 — A hydroelectric scheme and its energy changes","width":5.6,"w":1092,"h":654},{"type":"h","text":"Why alternative energy is important to the Caribbean"},{"type":"steps","items":["**Cost**: imported oil is expensive; alternative sources cut the oil import bill and save foreign exchange.","**Energy security**: islands are not at the mercy of world oil price rises or supply problems.","**Natural resources**: the region has abundant sunshine all year, steady trade winds, volcanic heat (in some islands) and rivers (in mainland territories like Guyana).","**Environment**: less burning of fossil fuels means less CO~2~ and pollution. Small islands are very vulnerable to climate change (sea-level rise, stronger hurricanes, coral bleaching).","**Jobs and development**: installing and maintaining solar, wind and geothermal systems creates local employment."]},{"type":"remember","text":"Almost all our energy comes originally from the **Sun**: fossil fuels and biomass (plants used sunlight in photosynthesis), wind (uneven heating of air by the Sun), hydro (the Sun evaporates water, which falls as rain on high land). Exceptions: geothermal, nuclear and tidal (the Moon)."},{"type":"tip","text":"In a 'discuss' question give a balanced answer: name the source, state the energy change, give at least one advantage AND one disadvantage, and link to the Caribbean (sunshine, trade winds, volcanoes, cost of imported oil)."}],"examples":[{"id":"week04.4.2.e1","title":"Solar energy in the Caribbean","question":"Give FOUR reasons why solar energy is a suitable alternative energy source for a Caribbean island such as Barbados.","steps":[{"label":"Resource","text":"The Caribbean gets strong sunshine for most of the year (tropical latitude)."},{"label":"Cost","text":"Sunlight is free, so it reduces the cost of importing oil for electricity."},{"label":"Environment","text":"Solar panels give no pollution or CO~2~ while working, protecting islands that are vulnerable to climate change."},{"label":"Practical","text":"Panels and solar water heaters can be fixed on roofs of individual homes, need little maintenance and have no moving parts."}],"answer":"Plenty of sunshine; free (reduces oil imports); no pollution; easy to install on roofs/little maintenance."},{"id":"week04.4.2.e2","title":"Choosing a source for an island","question":"Dominica is a mountainous volcanic island with many rivers. Suggest TWO renewable sources suited to it and state the energy change in each.","steps":[{"label":"Source 1","text":"Hydroelectric — rivers flowing from high mountains. GPE of water → KE → electrical energy."},{"label":"Source 2","text":"Geothermal — volcanic activity heats rocks underground. Thermal (heat) energy → KE of steam/turbine → electrical energy."}],"answer":"Hydroelectric (GPE → KE → electrical) and geothermal (heat → KE → electrical)."}]},"tryit":[{"id":"week04.4.2.p1","kind":"self","q":"Distinguish between renewable and non-renewable energy sources, giving ONE example of each.","marks":4,"level":3,"lines":4,"scheme":"Renewable: naturally replaced / will not run out (1), e.g. solar/wind (1). Non-renewable: used up faster than it is replaced / will run out (1), e.g. coal/oil/natural gas (1).","points":[{"text":"Renewable: naturally replaced / will not run out","marks":1},{"text":"e.g. solar/wind","marks":1},{"text":"Non-renewable: used up faster than it is replaced / will run out","marks":1},{"text":"e.g. coal/oil/natural gas","marks":1}],"section":"try","hint":{"text":"Look back at Example 2 (Choosing a source for an island). Start like this: Source 1: Hydroelectric — rivers flowing from high mountains. GPE of water → KE → electrical energy.","from":2}},{"id":"week04.4.2.p2","kind":"self","q":"State the energy changes that take place in a hydroelectric power station.","marks":2,"level":2,"lines":2,"scheme":"GPE of water → KE of water/turbine (1) → electrical energy (1).","points":[{"text":"GPE of water → KE of water/turbine","marks":1},{"text":"→ electrical energy","marks":1}],"section":"try"}],"practice":[{"id":"week04.4.2.p3","kind":"self","q":"Give TWO advantages and TWO disadvantages of using wind turbines.","marks":4,"level":3,"lines":4,"scheme":"Advantages (any 2): free; renewable; no pollution/CO₂; trade winds are steady (1 each). Disadvantages (any 2): wind not always blowing; noisy; visual impact; hurricane damage; high starting cost (1 each).","points":[{"text":"Advantages (any 2): free; renewable; no pollution/CO₂; trade winds are steady (1 each). Disadvantages (any 2): wind not always blowing; noisy; visual impact; hurricane damage; high starting cost (1 each).","marks":4,"each":true}],"section":"practice"},{"id":"week04.4.2.p4","kind":"self","q":"Explain why geothermal energy is possible in St Lucia but not in Barbados.","marks":2,"level":2,"lines":3,"scheme":"St Lucia is volcanic — hot rocks/steam are near the surface (1); Barbados is not volcanic (coral limestone), so there is no accessible underground heat (1).","points":[{"text":"St Lucia is volcanic — hot rocks/steam are near the surface","marks":1},{"text":"Barbados is not volcanic (coral limestone), so there is no accessible underground heat","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Solar energy in the Caribbean). Start like this: Resource: The Caribbean gets strong sunshine for most of the year (tropical latitude).","from":1}},{"id":"week04.4.2.p5","kind":"self","q":"What is **bagasse** and how can it be used as an energy source?","marks":2,"level":2,"lines":3,"scheme":"The fibrous waste left after juice is crushed from sugar cane (1); it is burned to boil water/make steam to drive turbines/generators in sugar factories (biomass) (1).","points":[{"text":"The fibrous waste left after juice is crushed from sugar cane","marks":1},{"text":"it is burned to boil water/make steam to drive turbines/generators in sugar factories (biomass)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Solar energy in the Caribbean). Start like this: Resource: The Caribbean gets strong sunshine for most of the year (tropical latitude).","from":1}},{"id":"week04.4.2.p6","kind":"self","q":"Explain why it is important for Caribbean countries to develop alternative energy sources. Give FOUR points.","marks":4,"level":3,"lines":6,"scheme":"Any 4 (1 each): reduce cost of imported oil/save foreign exchange; energy security/protection from oil price rises; fossil fuels will run out; abundant sun/wind/geothermal resources; reduce pollution/CO₂ and climate change (islands vulnerable); create local jobs.","points":[{"text":"Any 4 (1 each): reduce cost of imported oil/save foreign exchange; energy security/protection from oil price rises; fossil fuels will run out; abundant sun/wind/geothermal resources; reduce pollution/CO₂ and climate change (islands vulnerable); create local jobs.","marks":4,"each":true}],"section":"practice","hint":{"text":"Look back at Example 1 (Solar energy in the Caribbean). Start like this: Resource: The Caribbean gets strong sunshine for most of the year (tropical latitude).","from":1}}],"exit":[{"id":"week04.4.2.p7","kind":"self","q":"Explain how the energy in (a) fossil fuels and (b) wind both come originally from the Sun.","marks":3,"level":2,"lines":4,"scheme":"(a) Plants used sunlight in photosynthesis to store chemical energy (1); their remains formed coal/oil/gas over millions of years (1). (b) The Sun heats the Earth's surface unevenly, so warm air rises and cooler air moves in — wind (1).","points":[{"text":"(a) Plants used sunlight in photosynthesis to store chemical energy","marks":1},{"text":"their remains formed coal/oil/gas over millions of years","marks":1},{"text":"(b) The Sun heats the Earth's surface unevenly, so warm air rises and cooler air moves in — wind","marks":1}],"section":"exit"},{"id":"week04.4.2.p8","kind":"self","q":"Suggest why tidal power is not used much in the Caribbean.","marks":1,"level":1,"lines":2,"scheme":"The tidal range (difference between high and low tide) is very small in the Caribbean, so little energy is available (1).","points":[{"text":"The tidal range (difference between high and low tide) is very small in the Caribbean, so little energy is available","marks":1}],"section":"exit"}],"warmup":[{"id":"week04.4.2.w1","kind":"num","q":"A force of 25 N pushes a trolley through 8.0 m. Calculate the work done.","marks":2,"level":2,"lines":2,"scheme":"⟪W=F\\times d=25\\times 8.0⟫ (1) ⟪=200\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪W=F\\times d=25\\times 8.0⟫","marks":1},{"text":"⟪=200\\,\\mathrm{J}⟫","marks":1}],"num":{"value":200,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week04.4.1.p4"},{"id":"week04.4.2.w2","kind":"self","q":"Define the **joule**.","marks":2,"level":2,"lines":2,"scheme":"The work done when a force of 1 N (1) moves its point of application 1 m in the direction of the force (1).","points":[{"text":"The work done when a force of 1 N","marks":1},{"text":"moves its point of application 1 m in the direction of the force","marks":1}],"section":"warmup","src":"week04.4.1.p3"},{"id":"week04.4.2.w3","kind":"self","q":"Define **energy** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"The ability/capacity to do work (1); joule, J (1).","points":[{"text":"The ability/capacity to do work","marks":1},{"text":"joule, J","marks":1}],"section":"warmup","src":"week04.4.1.p1"}],"n":23},{"id":"week04.4.3","kind":"unit","unit":"4.3","title":"Potential Energy and Kinetic Energy","titleText":"Potential Energy and Kinetic Energy","goals":[{"code":"A5.6","text":"Define potential energy"},{"code":"A5.7","text":"Calculate changes in gravitational potential energy using ⟪\\Delta E_{p}=mg\\Delta h⟫"},{"code":"A5.8","text":"Define kinetic energy"},{"code":"A5.9","text":"Calculate kinetic energy using ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫"}],"codes":["A5.6","A5.7","A5.8","A5.9"],"words":[{"term":"Energy","def":"The ability (capacity) to do work."},{"term":"Work done","def":"Force × distance moved in the direction of the force."},{"term":"Potential energy","def":"Energy stored because of position or condition."},{"term":"Kinetic energy","def":"Energy an object has because of its motion."}],"learn":{"notes":[{"type":"h","text":"Potential energy (A5.6)"},{"type":"def","term":"Potential energy (PE)","text":"the energy stored in an object because of its position or its condition (state)."},{"type":"bullets","items":["**Gravitational PE** — because of its height above the ground (position).","**Elastic (strain) PE** — because it is stretched, squashed or twisted (condition), e.g. a stretched rubber band, a wound-up clock spring.","**Chemical PE** — stored in fuels, food and batteries."]},{"type":"h","text":"Change in gravitational PE (A5.7)"},{"type":"p","text":"Lifting an object of mass m through a height Δh needs a force equal to its weight (mg) acting through a distance Δh. Work done = force × distance ⟪=mg\\times \\Delta h⟫. This work is stored as gravitational potential energy."},{"type":"formula","tex":"\\Delta E_{p}=mg\\Delta h","where":["⟪\\Delta E_{p}⟫ = change in gravitational potential energy (J)","⟪m⟫ = mass (kg) — NOT weight","⟪g⟫ = 10 N kg^−1^ (gravitational field strength)","⟪\\Delta h⟫ = change in VERTICAL height (m)"],"label":"GRAVITATIONAL POTENTIAL ENERGY"},{"type":"img","src":"img/week04/pe_graph","alt":"Figure 4.3 — Potential energy against height for a 2.0 kg mass: a straight line through the origin. Gradient = 60 J ÷ 3.0 m = 20 N = mg.","caption":"Figure 4.3 — Potential energy against height for a 2.0 kg mass: a straight line through the origin. Gradient ⟪=60\\,\\mathrm{J}\\div 3.0\\,\\mathrm{m}=20\\,\\mathrm{N}=mg⟫.","width":4,"w":934,"h":614},{"type":"h","text":"Kinetic energy (A5.8)"},{"type":"def","term":"Kinetic energy (KE)","text":"the energy an object possesses because of its motion."},{"type":"formula","tex":"E_{k}=\\tfrac{1}{2}mv^{2}","where":["⟪E_{k}⟫ = kinetic energy (J)","⟪m⟫ = mass (kg)","⟪v⟫ = speed (m s^−1^) — ONLY v is squared"],"label":"KINETIC ENERGY"},{"type":"p","text":"**Where does ½mv^2^ come from?** (for understanding) A force F accelerates a mass m from rest through distance d. Work done ⟪=F\\times d=(ma)\\times d⟫. From the equations of motion, ⟪v^{2}=2ad⟫, so ⟪ad=\\tfrac{1}{2}v^{2}⟫. Therefore work done ⟪=m\\times \\tfrac{1}{2}v^{2}=\\tfrac{1}{2}mv^{2}⟫ — the KE gained."},{"type":"table","headers":["If you…","KE becomes…","Why"],"rows":[["double the mass","2 × bigger","⟪E_{k}\\propto m⟫"],["double the speed","4 × bigger","⟪E_{k}\\propto v^{2}\\ (2^{2}=4)⟫"],["triple the speed","9 × bigger","⟪3^{2}=9⟫"],["halve the speed","¼ of the original","⟪(\\tfrac{1}{2})^{2}=\\tfrac{1}{4}⟫"]]},{"type":"tip","text":"This is why speeding is so dangerous: a car at 100 km/h has about 4 times the KE of the same car at 50 km/h, so it needs about 4 times the braking distance and does far more damage in a crash."},{"type":"warn","text":"Common errors: (1) squaring ½m as well as v — square v FIRST, then multiply by ½ and m; (2) using grams instead of kilograms; (3) using km/h instead of m s^−1^; (4) using weight (N) instead of mass (kg) in mgh."}],"examples":[{"id":"week04.4.3.e1","title":"Gain in PE","question":"A 2.0 kg book is lifted from the floor to a shelf 1.8 m high. Calculate the gain in gravitational potential energy.","steps":[{"label":"Formula","text":"⟪\\Delta E_{p}=mg\\Delta h⟫"},{"label":"Substitute","text":"⟪\\Delta E_{p}=2.0\\times 10\\times 1.8⟫"},{"label":"Answer","text":"⟪\\Delta E_{p}=36\\,\\mathrm{J}⟫"}],"answer":"36 J"},{"id":"week04.4.3.e2","title":"KE of a car","question":"A car of mass 800 kg travels at 15 m s^−1^. Calculate its kinetic energy.","steps":[{"label":"Formula","text":"⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫"},{"label":"Square v first","text":"⟪v^{2}=15^{2}=225⟫"},{"label":"Substitute","text":"⟪E_{k}=\\tfrac{1}{2}\\times 800\\times 225⟫"},{"label":"Answer","text":"⟪E_{k}=90\\,000\\,\\mathrm{J}=90\\,\\mathrm{kJ}⟫"}],"answer":"90 000 J (90 kJ)"},{"id":"week04.4.3.e3","title":"Finding speed from KE","question":"A 0.50 kg ball has 25 J of kinetic energy. How fast is it moving?","steps":[{"label":"Rearrange","text":"⟪E_{k}=\\tfrac{1}{2}mv^{2}\\rightarrow v^{2}=2E_{k}\\div m⟫"},{"label":"Substitute","text":"⟪v^{2}=(2\\times 25)\\div 0.50=50\\div 0.50=100⟫"},{"label":"Square root","text":"⟪v=\\sqrt{100}⟫"},{"label":"Answer","text":"⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"10 m s^−1^"},{"id":"week04.4.3.e4","title":"Using a graph","question":"Figure 4.3 shows how the PE of an object changes with height. Use the gradient to find the mass of the object.","steps":[{"label":"Gradient","text":"⟪\\Delta E\\div \\Delta h=(80-20)\\div (4.0-1.0)=60\\div 3.0=20\\,\\mathrm{J}\\,\\mathrm{m}^{-1}\\ (=20\\,\\mathrm{N})⟫"},{"label":"Link to formula","text":"⟪E_{p}=(mg)\\times h⟫, so gradient ⟪=mg⟫"},{"label":"Solve","text":"⟪m=20\\div 10⟫"},{"label":"Answer","text":"⟪m=2.0\\,\\mathrm{kg}⟫"}],"answer":"⟪m=2.0\\,\\mathrm{kg}⟫"}]},"tryit":[{"id":"week04.4.3.p1","kind":"self","q":"Define (a) potential energy (b) kinetic energy.","marks":2,"level":2,"lines":3,"scheme":"(a) Energy stored in an object because of its position or condition/state (1). (b) Energy an object has because of its motion (1).","points":[{"text":"(a) Energy stored in an object because of its position or condition/state","marks":1},{"text":"(b) Energy an object has because of its motion","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Gain in PE). Start like this: Formula: ⟪\\Delta E_{p}=mg\\Delta h⟫","from":1}},{"id":"week04.4.3.p2","kind":"self","q":"Name the type of energy stored in (a) a stretched bow (b) a book on a high shelf.","marks":2,"level":2,"lines":2,"scheme":"(a) Elastic/strain potential energy (1). (b) Gravitational potential energy (1).","points":[{"text":"(a) Elastic/strain potential energy","marks":1},{"text":"(b) Gravitational potential energy","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Gain in PE). Start like this: Formula: ⟪\\Delta E_{p}=mg\\Delta h⟫","from":1}}],"practice":[{"id":"week04.4.3.p3","kind":"num","q":"A 60 kg student climbs stairs of vertical height 4.0 m. Calculate her gain in gravitational PE.","marks":2,"level":2,"lines":2,"scheme":"⟪\\Delta Ep=mg\\Delta h=60\\times 10\\times 4.0⟫ (1) ⟪=2400\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪\\Delta Ep=mg\\Delta h=60\\times 10\\times 4.0⟫","marks":1},{"text":"⟪=2400\\,\\mathrm{J}⟫","marks":1}],"num":{"value":2400,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (Gain in PE). Start like this: Formula: ⟪\\Delta E_{p}=mg\\Delta h⟫","from":1}},{"id":"week04.4.3.p4","kind":"num","q":"A 0.20 kg cricket ball moves at 30 m s^−1^. Calculate its KE.","marks":2,"level":2,"lines":2,"scheme":"⟪Ek=\\tfrac{1}{2}\\times 0.20\\times 30^{2}=\\tfrac{1}{2}\\times 0.20\\times 900⟫ (1) ⟪=90\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪Ek=\\tfrac{1}{2}\\times 0.20\\times 30^{2}=\\tfrac{1}{2}\\times 0.20\\times 900⟫","marks":1},{"text":"⟪=90\\,\\mathrm{J}⟫","marks":1}],"num":{"value":90,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (Gain in PE). Start like this: Formula: ⟪\\Delta E_{p}=mg\\Delta h⟫","from":1}},{"id":"week04.4.3.p5","kind":"num","q":"A 3000 kg truck travels at 20 m s^−1^. Calculate its KE, giving your answer in standard form.","marks":2,"level":2,"lines":2,"scheme":"⟪Ek=\\tfrac{1}{2}\\times 3000\\times 400⟫ (1) ⟪=600\\,000\\,\\mathrm{J}=6.0\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪Ek=\\tfrac{1}{2}\\times 3000\\times 400⟫","marks":1},{"text":"⟪=600\\,000\\,\\mathrm{J}=6.0\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":600000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (KE of a car). Start like this: Formula: ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫","from":2}},{"id":"week04.4.3.p6","kind":"num","q":"A stone of mass 50 g is thrown at 12 m s^−1^. Calculate its KE.","marks":3,"level":2,"lines":3,"scheme":"⟪m=0.050\\,\\mathrm{kg}⟫ (1); ⟪Ek=\\tfrac{1}{2}\\times 0.050\\times 144⟫ (1) ⟪=3.6\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪m=0.050\\,\\mathrm{kg}⟫","marks":1},{"text":"⟪Ek=\\tfrac{1}{2}\\times 0.050\\times 144⟫","marks":1},{"text":"⟪=3.6\\,\\mathrm{J}⟫","marks":1}],"num":{"value":3.6,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (KE of a car). Start like this: Formula: ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫","from":2}},{"id":"week04.4.3.p7","kind":"self","q":"A 4.0 kg mass gains 200 J of gravitational PE. Through what height was it raised?","marks":2,"level":2,"lines":3,"scheme":"⟪\\Delta h=\\Delta Ep\\div (mg)=200\\div (4.0\\times 10)⟫ (1) ⟪=5.0\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪\\Delta h=\\Delta Ep\\div (mg)=200\\div (4.0\\times 10)⟫","marks":1},{"text":"⟪=5.0\\,\\mathrm{m}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (Using a graph). Start like this: Gradient: ⟪\\Delta E\\div \\Delta h=(80-20)\\div (4.0-1.0)=60\\div 3.0=20\\,\\mathrm{J}\\,\\mathrm{m}^{-1}\\ (=20\\,\\mathrm{N})⟫","from":4}},{"id":"week04.4.3.p8","kind":"self","q":"The speed of a car is doubled. By what factor does its KE increase? Explain.","marks":2,"level":2,"lines":2,"scheme":"4 times (1); ⟪KE\\propto v^{2}⟫, and ⟪2^{2}=4⟫ (1).","points":[{"text":"4 times","marks":1},{"text":"⟪KE\\propto v^{2}⟫, and ⟪2^{2}=4⟫","marks":1}],"section":"practice"}],"exit":[{"id":"week04.4.3.p9","kind":"num","q":"A car of mass 1200 kg has KE of 240 000 J. Calculate its speed.","marks":3,"level":2,"lines":3,"scheme":"⟪v^{2}=2Ek\\div m=2\\times 240\\,000\\div 1200⟫ (1) ⟪=400⟫ (1); ⟪v=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"⟪v^{2}=2Ek\\div m=2\\times 240\\,000\\div 1200⟫","marks":1},{"text":"⟪=400⟫","marks":1},{"text":"⟪v=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":20,"sf":1,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"section":"exit"},{"id":"week04.4.3.p10","kind":"self","q":"A 1000 kg car travels at 72 km/h. Convert the speed to m s^−1^ and calculate the KE.","marks":3,"level":2,"lines":3,"scheme":"⟪72\\div 3.6=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1); ⟪Ek=\\tfrac{1}{2}\\times 1000\\times 20^{2}⟫ (1) ⟪=200\\,000\\,\\mathrm{J}=2.0\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪72\\div 3.6=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1},{"text":"⟪Ek=\\tfrac{1}{2}\\times 1000\\times 20^{2}⟫","marks":1},{"text":"⟪=200\\,000\\,\\mathrm{J}=2.0\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"section":"exit"}],"warmup":[{"id":"week04.4.3.w1","kind":"self","q":"Suggest why tidal power is not used much in the Caribbean.","marks":1,"level":1,"lines":2,"scheme":"The tidal range (difference between high and low tide) is very small in the Caribbean, so little energy is available (1).","points":[{"text":"The tidal range (difference between high and low tide) is very small in the Caribbean, so little energy is available","marks":1}],"section":"warmup","src":"week04.4.2.p8"},{"id":"week04.4.3.w2","kind":"self","q":"Explain why geothermal energy is possible in St Lucia but not in Barbados.","marks":2,"level":2,"lines":3,"scheme":"St Lucia is volcanic — hot rocks/steam are near the surface (1); Barbados is not volcanic (coral limestone), so there is no accessible underground heat (1).","points":[{"text":"St Lucia is volcanic — hot rocks/steam are near the surface","marks":1},{"text":"Barbados is not volcanic (coral limestone), so there is no accessible underground heat","marks":1}],"section":"warmup","src":"week04.4.2.p4"},{"id":"week04.4.3.w3","kind":"self","q":"What is **bagasse** and how can it be used as an energy source?","marks":2,"level":2,"lines":3,"scheme":"The fibrous waste left after juice is crushed from sugar cane (1); it is burned to boil water/make steam to drive turbines/generators in sugar factories (biomass) (1).","points":[{"text":"The fibrous waste left after juice is crushed from sugar cane","marks":1},{"text":"it is burned to boil water/make steam to drive turbines/generators in sugar factories (biomass)","marks":1}],"section":"warmup","src":"week04.4.2.p5"}],"n":24},{"id":"week04.4.4","kind":"unit","unit":"4.4","title":"Conservation of Energy, Power and Efficiency","titleText":"Conservation of Energy, Power and Efficiency","goals":[{"code":"A5.10","text":"Apply the law of conservation of energy"},{"code":"A5.11","text":"Define power and use ⟪P=E/t⟫"},{"code":"A5.12","text":"Explain efficiency and the factors that affect the efficiency of a system"},{"code":"A5.13","text":"Calculate the efficiency of energy conversions"}],"codes":["A5.10","A5.11","A5.12","A5.13"],"words":[{"term":"Energy","def":"The ability (capacity) to do work."},{"term":"Work done","def":"Force × distance moved in the direction of the force."},{"term":"Joule","def":"Work done when a 1 N force moves its point of application 1 m in the direction of the force."},{"term":"Conservation of energy","def":"Energy cannot be created or destroyed, only changed from one form to another."},{"term":"Power","def":"Rate of doing work / rate of energy conversion."},{"term":"Watt","def":"One joule per second."},{"term":"Efficiency","def":"Useful output ÷ total input, × 100%."}],"learn":{"notes":[{"type":"h","text":"The law of conservation of energy (A5.10)"},{"type":"def","term":"Law of conservation of energy","text":"energy cannot be created or destroyed; it can only be changed (transformed) from one form to another. The total energy of a closed system stays constant."},{"type":"p","text":"When energy seems to 'disappear', it has usually been changed into **heat** (by friction or air resistance) and **sound**. This energy spreads out into the surroundings and is hard to use again — we call it **wasted** energy, but it is NOT destroyed."},{"type":"h","text":"Example 1 — the swinging pendulum"},{"type":"img","src":"img/week04/pendulum_energy","alt":"Figure 4.4 — Energy changes in a swinging pendulum","caption":"Figure 4.4 — Energy changes in a swinging pendulum","width":4.4,"w":1014,"h":572},{"type":"steps","items":["At **A** the bob is momentarily at rest at its highest point: maximum GPE, zero KE.","From A to **B** it falls: GPE → KE. At B (lowest point) KE and speed are maximum, GPE is minimum.","From B to **C** it rises: KE → GPE. At C it stops again: maximum GPE, zero KE.","Each swing a little energy is changed to heat by air resistance and friction at the support, so the swings slowly die away. The total energy (⟪GPE+KE⟫ + heat) is always the same."]},{"type":"h","text":"Example 2 — falling and rolling objects"},{"type":"img","src":"img/week04/ramp_energy","alt":"Figure 4.5 — On a smooth (frictionless) track the PE lost equals the KE gained","caption":"Figure 4.5 — On a smooth (frictionless) track the PE lost equals the KE gained","width":4.8,"w":1094,"h":516},{"type":"formula","tex":"\\text{loss of }PE=\\text{ gain of }KE\\qquad mgh=\\tfrac{1}{2}mv^{2}\\text{ so }v=\\sqrt{2\\,\\mathrm{g}\\,\\mathrm{h}}","where":["Only true when friction and air resistance can be ignored.","The mass cancels — all objects dropped from the same height reach the same speed (ignoring air resistance).","If friction acts: PE lost ⟪=KE⟫ gained + work done against friction (heat)."],"label":"CONSERVATION OF ENERGY"},{"type":"h","text":"Power (A5.11)"},{"type":"def","term":"Power","text":"the rate of doing work, or the rate at which energy is converted (transferred)."},{"type":"formula","tex":"P=E\\div t=W\\div t","where":["⟪P⟫ = power in watts (W)","⟪E⟫ = energy converted or W = work done, in joules (J)","⟪t⟫ = time in seconds (s)","⟪1\\,\\mathrm{W}⟫ = 1 J s^−1^;  ⟪1\\,\\mathrm{kW}=1000\\,\\mathrm{W}⟫;  ⟪1\\,\\mathrm{MW}=1\\,000\\,000\\,\\mathrm{W}⟫"],"label":"POWER"},{"type":"def","term":"The watt","text":"a power of one joule per second ⟪(1\\,\\mathrm{W}=1\\,\\mathrm{J}\\,\\mathrm{s}^{-1})⟫."},{"type":"p","text":"A 2000 W kettle converts 2000 J of electrical energy into heat every second. Two people who lift the same load to the same height do the same work, but the one who does it faster has the greater power."},{"type":"h","text":"Activity: measuring your own power (running up stairs)"},{"type":"img","src":"img/week04/stairs_power","alt":"Figure 4.6 — Measuring personal power","caption":"Figure 4.6 — Measuring personal power","width":4.6,"w":1054,"h":579},{"type":"steps","items":["**Apparatus:** bathroom scale, metre rule, stopwatch, a flight of stairs.","Find your mass m (kg) on the scale. Weight ⟪=mg⟫.","Measure the height of one step with the metre rule and count the steps. Vertical height h = height of one step × number of steps.","A partner times how long (t) it takes you to run up the stairs from the bottom step to the top step.","Repeat three times and find the average time.","**Calculate:** work done against gravity ⟪=mgh⟫;  power ⟪P=mgh\\div t⟫."]},{"type":"bullets","items":["**Precautions:** measure VERTICAL height (not the slope length); measure several steps and average (steps may not be equal); start and stop the watch exactly at the bottom and top; be safe — do not race on wet or crowded stairs.","**Typical result:** a 60 kg student climbing 3.0 m in ⟪4.0\\,\\mathrm{s}\\rightarrow P=60\\times 10\\times 3.0\\div 4.0=450\\,\\mathrm{W}⟫.","**Conclusion:** the faster you run up the same stairs, the greater your power, even though the work done (mgh) is the same."]},{"type":"h","text":"Efficiency (A5.12 and A5.13)"},{"type":"def","term":"Efficiency","text":"the ratio of the useful energy (or power) output to the total energy (or power) input, usually given as a percentage."},{"type":"formula","tex":"\\text{efficiency }=(\\text{useful energy output }\\div \\text{ total energy input})\\times 100\\%","where":["or: efficiency = (useful power output ÷ total power input) × 100%","Efficiency has NO unit (it is a ratio or a percentage).","Wasted energy = total input − useful output.","No real machine is 100% efficient; efficiency is always less than 100%."],"label":"EFFICIENCY"},{"type":"img","src":"img/week04/sankey_lamp","alt":"Figure 4.7 — Sankey (energy-flow) diagram for a filament lamp: efficiency = 10 ÷ 100 × 100% = 10%","caption":"Figure 4.7 — Sankey (energy-flow) diagram for a filament lamp: efficiency ⟪=10\\div 100\\times 100\\%=10\\%⟫","width":4.8,"w":1033,"h":574},{"type":"table","headers":["Factor that lowers efficiency","Why energy is wasted","How to improve efficiency"],"rows":[["Friction between moving parts","work against friction → heat (and sound)","lubricate (oil/grease); use ball bearings; smooth surfaces"],["Air resistance (drag)","work against air → heat","streamlined shape"],["Heat loss from hot parts","heat escapes to the surroundings","insulate (lagging); reduce the temperature difference"],["Electrical resistance of wires","current heats the wires","thicker/low-resistance wires; transmit at high voltage"],["Noise and vibration","energy carried away as sound","tighten loose parts; good maintenance"],["Wear and poor maintenance","worn parts rub more","regular servicing; replace worn parts"]]},{"type":"p","text":"Typical efficiencies: filament lamp ≈ 5–10% (most energy becomes heat); petrol car engine ≈ 25–30%; electric motor ≈ 70–90%; large transformer ≈ 98%. An LED or fluorescent lamp gives the same light as a filament lamp using far less electrical energy, so it is much more efficient."},{"type":"warn","text":"An efficiency above 100% means you have divided the wrong way round (input ÷ output). Useful OUTPUT goes on TOP."}],"examples":[{"id":"week04.4.4.e1","title":"Speed of a falling ball","question":"A ball is dropped from a height of 5.0 m. Ignoring air resistance, calculate its speed just before it hits the ground.","steps":[{"label":"Principle","text":"loss of PE = gain of KE:  mgh = ½mv^2^ (m cancels)"},{"label":"Rearrange","text":"⟪v^{2}=2gh⟫"},{"label":"Substitute","text":"⟪v^{2}=2\\times 10\\times 5.0=100⟫"},{"label":"Answer","text":"⟪v=\\sqrt{100}=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"10 m s^−1^"},{"id":"week04.4.4.e2","title":"Pendulum speed","question":"A pendulum bob of mass 0.10 kg is pulled aside so that it is raised 0.20 m above its lowest point, then released. Calculate (a) the PE gained (b) its maximum speed.","steps":[{"label":"(a) PE","text":"⟪E_{p}=mgh=0.10\\times 10\\times 0.20=0.20\\,\\mathrm{J}⟫"},{"label":"(b) Principle","text":"At the lowest point all this PE has become KE: ⟪\\tfrac{1}{2}mv^{2}=0.20\\,\\mathrm{J}⟫"},{"label":"Rearrange","text":"⟪v^{2}=2\\times 0.20\\div 0.10=4.0⟫"},{"label":"Answer","text":"⟪v=\\sqrt{4.0}=2.0\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫"}],"answer":"(a) 0.20 J  (b) 2.0 m s^−1^"},{"id":"week04.4.4.e3","title":"Power running up stairs","question":"A 60 kg boy runs up a flight of stairs of vertical height 3.0 m in 4.0 s. Calculate his power.","steps":[{"label":"Work done","text":"⟪E=mgh=60\\times 10\\times 3.0=1800\\,\\mathrm{J}⟫"},{"label":"Formula","text":"⟪P=E\\div t⟫"},{"label":"Substitute","text":"⟪P=1800\\div 4.0⟫"},{"label":"Answer","text":"⟪P=450\\,\\mathrm{W}⟫"}],"answer":"450 W"},{"id":"week04.4.4.e4","title":"Efficiency of a motor","question":"An electric motor uses 500 J of electrical energy to lift a 20 kg load through 2.0 m. Calculate (a) the useful energy output (b) the efficiency (c) the energy wasted.","steps":[{"label":"(a) Useful output","text":"⟪mgh=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫"},{"label":"(b) Formula","text":"efficiency = (useful output ÷ input) × 100%"},{"label":"Substitute","text":"⟪=(400\\div 500)\\times 100\\%⟫"},{"label":"Answer","text":"efficiency ⟪=80\\%⟫"},{"label":"(c) Wasted","text":"⟪500-400=100\\,\\mathrm{J}⟫ (mainly heat and sound)"}],"answer":"(a) 400 J  (b) 80%  (c) 100 J"}]},"tryit":[{"id":"week04.4.4.p1","kind":"self","q":"State the law of conservation of energy.","marks":2,"level":2,"lines":3,"scheme":"Energy cannot be created or destroyed (1), only changed from one form to another (1).","points":[{"text":"Energy cannot be created or destroyed","marks":1},{"text":"only changed from one form to another","marks":1}],"section":"try","hint":{"text":"Look back at Example 4 (Efficiency of a motor). Start like this: (a) Useful output: ⟪mgh=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫","from":4}},{"id":"week04.4.4.p2","kind":"self","q":"A pendulum swings from A to B to C (Figure 4.4). (a) Where is its KE greatest? (b) Explain why the pendulum eventually stops swinging.","marks":3,"level":2,"lines":4,"scheme":"(a) At B, the lowest point (1). (b) Energy is gradually changed to heat (and sound) (1) by air resistance and friction at the support (1).","points":[{"text":"(a) At B, the lowest point","marks":1},{"text":"(b) Energy is gradually changed to heat (and sound)","marks":1},{"text":"by air resistance and friction at the support","marks":1}],"section":"try"}],"practice":[{"id":"week04.4.4.p3","kind":"self","q":"A 0.50 kg stone is dropped from a height of 20 m. Ignoring air resistance, calculate (a) its KE just before landing (b) its speed just before landing.","marks":4,"level":3,"lines":4,"scheme":"(a) KE gained ⟪=PE⟫ lost ⟪=mgh=0.50\\times 10\\times 20⟫ (1) ⟪=100\\,\\mathrm{J}⟫ (1). (b) ⟪v^{2}=2gh=2\\times 10\\times 20=400⟫ (1); ⟪v=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"(a) KE gained ⟪=PE⟫ lost ⟪=mgh=0.50\\times 10\\times 20⟫","marks":1},{"text":"⟪=100\\,\\mathrm{J}⟫","marks":1},{"text":"(b) ⟪v^{2}=2gh=2\\times 10\\times 20=400⟫","marks":1},{"text":"⟪v=20\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Speed of a falling ball). Start like this: Principle: loss of PE = gain of KE:  mgh = ½mv^2^ (m cancels)","from":1}},{"id":"week04.4.4.p4","kind":"self","q":"Define **power** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"The rate of doing work / rate of energy conversion (1); watt, ⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫ (1).","points":[{"text":"The rate of doing work / rate of energy conversion","marks":1},{"text":"watt, ⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Power running up stairs). Start like this: Work done: ⟪E=mgh=60\\times 10\\times 3.0=1800\\,\\mathrm{J}⟫","from":3}},{"id":"week04.4.4.p5","kind":"num","q":"A 2000 W kettle is switched on for 3.0 minutes. How much energy does it convert?","marks":2,"level":2,"lines":3,"scheme":"⟪E=P\\times t=2000\\times 180⟫ (1) ⟪=360\\,000\\,\\mathrm{J}\\ (3.6\\times 10^{5}\\,\\mathrm{J})⟫ (1).","points":[{"text":"⟪E=P\\times t=2000\\times 180⟫","marks":1},{"text":"⟪=360\\,000\\,\\mathrm{J}\\ (3.6\\times 10^{5}\\,\\mathrm{J})⟫","marks":1}],"num":{"value":360000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice"},{"id":"week04.4.4.p6","kind":"self","q":"A crane lifts an 800 kg load through 15 m in 20 s. Calculate (a) the work done (b) the power of the crane.","marks":3,"level":2,"lines":3,"scheme":"(a) ⟪W=mgh=800\\times 10\\times 15⟫ (1) ⟪=120\\,000\\,\\mathrm{J}⟫ (1). (b) ⟪P=120\\,000\\div 20=6000\\,\\mathrm{W}=6.0\\,\\mathrm{kW}⟫ (1).","points":[{"text":"(a) ⟪W=mgh=800\\times 10\\times 15⟫","marks":1},{"text":"⟪=120\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"(b) ⟪P=120\\,000\\div 20=6000\\,\\mathrm{W}=6.0\\,\\mathrm{kW}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (Efficiency of a motor). Start like this: (a) Useful output: ⟪mgh=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫","from":4}},{"id":"week04.4.4.p7","kind":"self","q":"A lamp converts 60 J of electrical energy every second into 6 J of light. (a) Calculate its efficiency. (b) What happens to the rest of the energy?","marks":3,"level":2,"lines":3,"scheme":"(a) ⟪(6\\div 60)\\times 100\\%⟫ (1) ⟪=10\\%⟫ (1). (b) The other 54 J is changed to heat (thermal energy) (1).","points":[{"text":"(a) ⟪(6\\div 60)\\times 100\\%⟫","marks":1},{"text":"⟪=10\\%⟫","marks":1},{"text":"(b) The other 54 J is changed to heat (thermal energy)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (Efficiency of a motor). Start like this: (a) Useful output: ⟪mgh=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫","from":4}},{"id":"week04.4.4.p8","kind":"self","q":"A motor is 75% efficient. Its input power is 400 W. Calculate its useful output power and its wasted power.","marks":2,"level":2,"lines":3,"scheme":"Useful ⟪=0.75\\times 400=300\\,\\mathrm{W}⟫ (1); wasted ⟪=400-300=100\\,\\mathrm{W}⟫ (1).","points":[{"text":"Useful ⟪=0.75\\times 400=300\\,\\mathrm{W}⟫","marks":1},{"text":"wasted ⟪=400-300=100\\,\\mathrm{W}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (Efficiency of a motor). Start like this: (a) Useful output: ⟪mgh=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫","from":4}},{"id":"week04.4.4.p9","kind":"self","q":"State THREE factors that reduce the efficiency of a machine such as a car engine, and for each one say how it could be reduced.","marks":3,"level":2,"lines":5,"scheme":"Any three, with a matching improvement (1 each): friction between moving parts — lubricate/ball bearings; heat losses — insulation/cooling design; air resistance — streamlining; noise/vibration — tighten/maintain parts; wear — regular servicing.","points":[{"text":"Any three, with a matching improvement (1 each): friction between moving parts — lubricate/ball bearings; heat losses — insulation/cooling design; air resistance — streamlining; noise/vibration — tighten/maintain parts; wear — regular servicing.","marks":3,"each":true}],"section":"practice"}],"exit":[{"id":"week04.4.4.p10","kind":"self","q":"A roller-coaster car of mass 500 kg starts at rest at the top of a 45 m drop. (a) Ignoring friction, calculate its speed at the bottom. (b) Its actual speed at the bottom is 28 m s^−1^. Calculate the energy lost to friction.","marks":5,"level":3,"lines":6,"scheme":"(a) ⟪v^{2}=2gh=2\\times 10\\times 45=900⟫ (1); ⟪v=30\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1). (b) PE lost ⟪=500\\times 10\\times 45=225\\,000\\,\\mathrm{J}⟫ (1); KE gained ⟪=\\tfrac{1}{2}\\times 500\\times 28^{2}=196\\,000\\,\\mathrm{J}⟫ (1); energy lost ⟪=29\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"(a) ⟪v^{2}=2gh=2\\times 10\\times 45=900⟫","marks":1},{"text":"⟪v=30\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1},{"text":"(b) PE lost ⟪=500\\times 10\\times 45=225\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"KE gained ⟪=\\tfrac{1}{2}\\times 500\\times 28^{2}=196\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"energy lost ⟪=29\\,000\\,\\mathrm{J}⟫","marks":1}],"section":"exit"},{"id":"week04.4.4.p11","kind":"self","q":"An electric pump lifts 300 kg of water through a vertical height of 8.0 m in 60 s. Its electrical input power is 600 W. Calculate (a) the useful output power (b) the efficiency of the pump.","marks":4,"level":3,"lines":5,"scheme":"(a) Useful energy ⟪=mgh=300\\times 10\\times 8.0=24\\,000\\,\\mathrm{J}⟫ (1); useful power ⟪=24\\,000\\div 60=400\\,\\mathrm{W}⟫ (1). (b) Efficiency ⟪=(400\\div 600)\\times 100\\%⟫ (1) ⟪=67\\%\\ (66.7\\%)⟫ (1).","points":[{"text":"(a) Useful energy ⟪=mgh=300\\times 10\\times 8.0=24\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"useful power ⟪=24\\,000\\div 60=400\\,\\mathrm{W}⟫","marks":1},{"text":"(b) Efficiency ⟪=(400\\div 600)\\times 100\\%⟫","marks":1},{"text":"⟪=67\\%\\ (66.7\\%)⟫","marks":1}],"section":"exit"}],"warmup":[{"id":"week04.4.4.w1","kind":"self","q":"Name the type of energy stored in (a) a stretched bow (b) a book on a high shelf.","marks":2,"level":2,"lines":2,"scheme":"(a) Elastic/strain potential energy (1). (b) Gravitational potential energy (1).","points":[{"text":"(a) Elastic/strain potential energy","marks":1},{"text":"(b) Gravitational potential energy","marks":1}],"section":"warmup","src":"week04.4.3.p2"},{"id":"week04.4.4.w2","kind":"num","q":"A 60 kg student climbs stairs of vertical height 4.0 m. Calculate her gain in gravitational PE.","marks":2,"level":2,"lines":2,"scheme":"⟪\\Delta Ep=mg\\Delta h=60\\times 10\\times 4.0⟫ (1) ⟪=2400\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪\\Delta Ep=mg\\Delta h=60\\times 10\\times 4.0⟫","marks":1},{"text":"⟪=2400\\,\\mathrm{J}⟫","marks":1}],"num":{"value":2400,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week04.4.3.p3"},{"id":"week04.4.4.w3","kind":"num","q":"A 0.20 kg cricket ball moves at 30 m s^−1^. Calculate its KE.","marks":2,"level":2,"lines":2,"scheme":"⟪Ek=\\tfrac{1}{2}\\times 0.20\\times 30^{2}=\\tfrac{1}{2}\\times 0.20\\times 900⟫ (1) ⟪=90\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪Ek=\\tfrac{1}{2}\\times 0.20\\times 30^{2}=\\tfrac{1}{2}\\times 0.20\\times 900⟫","marks":1},{"text":"⟪=90\\,\\mathrm{J}⟫","marks":1}],"num":{"value":90,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week04.4.3.p4"}],"n":25},{"id":"week04.4.5","kind":"unit","unit":"4.5","title":"Pressure in Solids and Liquids","titleText":"Pressure in Solids and Liquids","goals":[{"code":"A6.1","text":"Define pressure and use ⟪P=F/A⟫"},{"code":"A6.2","text":"Explain how pressure in a fluid depends on depth and use ⟪P=\\rho gh⟫"}],"codes":["A6.1","A6.2"],"words":[{"term":"Pressure","def":"Force acting normally per unit area."},{"term":"Pascal","def":"One newton per square metre."}],"learn":{"notes":[{"type":"h","text":"Pressure (A6.1)"},{"type":"def","term":"Pressure","text":"the force acting normally (at right angles) per unit area of a surface."},{"type":"formula","tex":"P=F\\div A","where":["⟪P⟫ = pressure in pascals (Pa)","⟪F⟫ = force acting at right angles to the surface, in newtons (N)","⟪A⟫ = area in square metres (m^2^)","⟪1\\,\\mathrm{Pa}⟫ = 1 N m^−2^;  ⟪1\\,\\mathrm{kPa}=1000\\,\\mathrm{Pa}⟫","Area: ⟪1\\,\\mathrm{cm}^{2}=1\\times 10^{-4}\\,\\mathrm{m}^{2}⟫ (divide by 10 000)"],"label":"PRESSURE"},{"type":"def","term":"The pascal","text":"a pressure of one newton per square metre ⟪(1\\,\\mathrm{Pa}=1\\,\\mathrm{N}\\,\\mathrm{m}^{-2})⟫."},{"type":"img","src":"img/week04/brick_pressure","alt":"Figure 4.8 — The same brick gives a different pressure on different faces","caption":"Figure 4.8 — The same brick gives a different pressure on different faces","width":5.2,"w":1110,"h":534},{"type":"p","text":"Same force, smaller area → **bigger pressure**. Same force, bigger area → **smaller pressure**."},{"type":"table","headers":["Large area → LOW pressure (spread the force)","Small area → HIGH pressure (concentrate the force)"],"rows":[["Wide tyres on tractors so they do not sink into soft soil","Sharp knife or cutlass — very thin edge cuts easily"],["Wide straps on a school bag so they do not dig into shoulders","Nails, needles and drawing pins have sharp points"],["Wide foundations under buildings","Stiletto heels can dent wooden floors"],["Snowshoes; camels' wide feet on sand","Studs on football boots grip the ground"]]},{"type":"h","text":"Pressure in liquids (A6.2)"},{"type":"bullets","items":["Pressure in a liquid **increases with depth**.","At any point, the pressure acts **equally in all directions**.","Pressure is the **same at all points at the same depth** (same horizontal level) in the same liquid.","Pressure depends on the **density** of the liquid: a denser liquid gives more pressure at the same depth.","Pressure does **NOT** depend on the shape or width of the container, or the area of the surface."]},{"type":"img","src":"img/week04/liquid_column","alt":"Figure 4.9 — The column of liquid above an area A at depth h","caption":"Figure 4.9 — The column of liquid above an area A at depth h","width":3,"w":683,"h":654},{"type":"p","text":"**Deriving **⟪\\boldsymbol{P=\\rho gh}⟫**.** Think of a column of liquid of height h standing on an area A. Volume ⟪=A\\times h⟫. Mass = density × volume ⟪=\\rho Ah⟫. Weight = mass × ⟪g=\\rho Ahg⟫. Pressure = weight ÷ area ⟪=\\rho Ahg\\div A=\\boldsymbol{\\rho gh}⟫."},{"type":"formula","tex":"P=\\rho gh","where":["⟪P⟫ = pressure due to the liquid (Pa)","⟪\\rho⟫ = density of the liquid (kg m^−3^); water ⟪=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫; sea water ≈ 1030 kg m^−3^","⟪g⟫ = 10 N kg^−1^","⟪h⟫ = depth below the surface (m)","Total pressure at depth h = atmospheric pressure + ρgh (atmospheric pressure ≈ ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫)"],"label":"PRESSURE IN A LIQUID"},{"type":"h","text":"Demonstration: pressure increases with depth"},{"type":"img","src":"img/week04/pressure_depth","alt":"Figure 4.10 — Left: water spurts furthest from the deepest hole. Right: a dam is thicker at the bottom.","caption":"Figure 4.10 — Left: water spurts furthest from the deepest hole. Right: a dam is thicker at the bottom.","width":5.6,"w":1365,"h":614},{"type":"steps","items":["**Apparatus:** a tall plastic bottle or can with three holes of the same size punched one above the other; water; a tray.","Cover the holes with tape and fill the can with water to the top.","Remove the tape and keep the can topped up so the water level stays constant.","**Observation:** the water from the lowest hole spurts out fastest and travels furthest.","**Conclusion:** the pressure in a liquid increases with depth."]},{"type":"h","text":"Applications in everyday life"},{"type":"bullets","items":["**Dams** are built much thicker at the base because the water pressure is greatest at the bottom.","**Water tanks** in Caribbean homes are placed on high stands or on the roof: the greater the height of water above the tap, the greater the pressure and the faster the flow.","**Divers** feel pain in their ears as they go deeper; submarines need very strong hulls.","A **drip (IV) bag** in hospital is hung high above the patient so the liquid's pressure is greater than the blood pressure in the vein."]},{"type":"warn","text":"In ⟪P=\\rho gh⟫, h is the DEPTH below the liquid surface — measured downwards from the surface, not upwards from the bottom of the container."}],"examples":[{"id":"week04.4.5.e1","title":"Brick on two faces","question":"A brick of weight 30 N measures ⟪0.20\\,\\mathrm{m}\\times 0.10\\,\\mathrm{m}\\times 0.05\\,\\mathrm{m}⟫. Calculate the pressure it exerts on the ground when it rests on (a) its largest face (b) its smallest face.","steps":[{"label":"(a) Area","text":"⟪A=0.20\\times 0.10=0.020\\,\\mathrm{m}^{2}⟫"},{"label":"Pressure","text":"⟪P=F\\div A=30\\div 0.020=1500\\,\\mathrm{Pa}⟫"},{"label":"(b) Area","text":"⟪A=0.10\\times 0.05=0.005\\,\\mathrm{m}^{2}⟫"},{"label":"Pressure","text":"⟪P=30\\div 0.005=6000\\,\\mathrm{Pa}⟫"}],"answer":"(a) 1500 Pa  (b) 6000 Pa — four times bigger because the area is four times smaller"},{"id":"week04.4.5.e2","title":"Stiletto heel","question":"A woman of weight 600 N stands with all her weight on one stiletto heel of area 1.0 cm^2^. Calculate the pressure on the floor.","steps":[{"label":"Convert area","text":"⟪1.0\\,\\mathrm{cm}^{2}=1.0\\times 10^{-4}\\,\\mathrm{m}^{2}⟫"},{"label":"Formula","text":"⟪P=F\\div A⟫"},{"label":"Substitute","text":"⟪P=600\\div (1.0\\times 10^{-4})⟫"},{"label":"Answer","text":"⟪P=6\\,000\\,000\\,\\mathrm{Pa}=6.0\\times 10^{6}\\,\\mathrm{Pa}⟫"}],"answer":"⟪6.0\\times 10^{6}\\,\\mathrm{Pa}⟫ — enough to dent a wooden floor"},{"id":"week04.4.5.e3","title":"Diving in the sea","question":"A diver is 15 m below the surface of the sea (density 1030 kg m^−3^). Calculate (a) the pressure due to the sea water (b) the total pressure on the diver, if atmospheric pressure is ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫.","steps":[{"label":"(a) Formula","text":"⟪P=\\rho gh⟫"},{"label":"Substitute","text":"⟪P=1030\\times 10\\times 15⟫"},{"label":"Answer","text":"⟪P=154\\,500\\,\\mathrm{Pa}\\approx 1.5\\times 10^{5}\\,\\mathrm{Pa}⟫"},{"label":"(b) Add atmosphere","text":"total ⟪=1.0\\times 10^{5}+1.545\\times 10^{5}=2.545\\times 10^{5}\\,\\mathrm{Pa}\\approx 2.5\\times 10^{5}\\,\\mathrm{Pa}⟫"}],"answer":"(a) ⟪1.5\\times 10^{5}\\,\\mathrm{Pa}⟫  (b) ⟪2.5\\times 10^{5}\\,\\mathrm{Pa}⟫"},{"id":"week04.4.5.e4","title":"Water tank on a stand","question":"The water surface in a tank on a stand is 6.0 m above a tap. Calculate the water pressure at the tap.","steps":[{"label":"Formula","text":"⟪P=\\rho gh⟫"},{"label":"Substitute","text":"⟪P=1000\\times 10\\times 6.0⟫"},{"label":"Answer","text":"⟪P=60\\,000\\,\\mathrm{Pa}=60\\,\\mathrm{kPa}⟫"}],"answer":"60 000 Pa (60 kPa)"}]},"tryit":[{"id":"week04.4.5.p1","kind":"self","q":"Define **pressure** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"Force acting normally/perpendicularly per unit area (1); pascal, ⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫ (1).","points":[{"text":"Force acting normally/perpendicularly per unit area","marks":1},{"text":"pascal, ⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Brick on two faces). Start like this: (a) Area: ⟪A=0.20\\times 0.10=0.020\\,\\mathrm{m}^{2}⟫","from":1}},{"id":"week04.4.5.p2","kind":"num","q":"A force of 200 N acts on an area of 0.50 m^2^. Calculate the pressure.","marks":2,"level":2,"lines":2,"scheme":"⟪P=F\\div A=200\\div 0.50⟫ (1) ⟪=400\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪P=F\\div A=200\\div 0.50⟫","marks":1},{"text":"⟪=400\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":400,"sf":1,"unit":"Pa","unitTex":"\\mathrm{Pa}"},"section":"try","hint":{"text":"Look back at Example 2 (Stiletto heel). Start like this: Convert area: ⟪1.0\\,\\mathrm{cm}^{2}=1.0\\times 10^{-4}\\,\\mathrm{m}^{2}⟫","from":2}}],"practice":[{"id":"week04.4.5.p3","kind":"num","q":"A box of weight 900 N has a base 0.60 m by 0.50 m. Calculate the pressure it exerts on the floor.","marks":3,"level":2,"lines":3,"scheme":"⟪A=0.60\\times 0.50=0.30\\,\\mathrm{m}^{2}⟫ (1); ⟪P=900\\div 0.30⟫ (1) ⟪=3000\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪A=0.60\\times 0.50=0.30\\,\\mathrm{m}^{2}⟫","marks":1},{"text":"⟪P=900\\div 0.30⟫","marks":1},{"text":"⟪=3000\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":3000,"sf":1,"unit":"Pa","unitTex":"\\mathrm{Pa}"},"section":"practice","hint":{"text":"Look back at Example 1 (Brick on two faces). Start like this: (a) Area: ⟪A=0.20\\times 0.10=0.020\\,\\mathrm{m}^{2}⟫","from":1}},{"id":"week04.4.5.p4","kind":"self","q":"Explain why a sharp knife cuts better than a blunt one.","marks":2,"level":2,"lines":3,"scheme":"A sharp edge has a very small area (1), so the same force produces a much larger pressure ⟪(P=F/A)⟫ (1).","points":[{"text":"A sharp edge has a very small area","marks":1},{"text":"so the same force produces a much larger pressure ⟪(P=F/A)⟫","marks":1}],"section":"practice"},{"id":"week04.4.5.p5","kind":"self","q":"Explain why tractors have wide tyres.","marks":2,"level":2,"lines":3,"scheme":"Wide tyres give a large area (1), so the pressure on the ground is small and the tractor does not sink into soft soil (1).","points":[{"text":"Wide tyres give a large area","marks":1},{"text":"so the pressure on the ground is small and the tractor does not sink into soft soil","marks":1}],"section":"practice"},{"id":"week04.4.5.p6","kind":"num","q":"Calculate the pressure due to the water at the bottom of a swimming pool 2.5 m deep.","marks":2,"level":2,"lines":2,"scheme":"⟪P=\\rho gh=1000\\times 10\\times 2.5⟫ (1) ⟪=25\\,000\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪P=\\rho gh=1000\\times 10\\times 2.5⟫","marks":1},{"text":"⟪=25\\,000\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":25000,"sf":2,"unit":"Pa","unitTex":"\\mathrm{Pa}"},"section":"practice","hint":{"text":"Look back at Example 3 (Diving in the sea). Start like this: (a) Formula: ⟪P=\\rho gh⟫","from":3}},{"id":"week04.4.5.p7","kind":"self","q":"At what depth in fresh water is the pressure due to the water equal to ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫?","marks":2,"level":2,"lines":3,"scheme":"⟪h=P\\div (\\rho g)=1.0\\times 10^{5}\\div (1000\\times 10)⟫ (1) ⟪=10\\,\\mathrm{m}⟫ (1).","points":[{"text":"⟪h=P\\div (\\rho g)=1.0\\times 10^{5}\\div (1000\\times 10)⟫","marks":1},{"text":"⟪=10\\,\\mathrm{m}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Diving in the sea). Start like this: (a) Formula: ⟪P=\\rho gh⟫","from":3}},{"id":"week04.4.5.p8","kind":"self","q":"Two containers, one wide and one narrow, are filled with water to the same depth. Compare the pressure at the bottom of each. Explain.","marks":2,"level":2,"lines":3,"scheme":"The pressure is the same (1); pressure depends only on depth (and density and g), not on the shape/width of the container (1).","points":[{"text":"The pressure is the same","marks":1},{"text":"pressure depends only on depth (and density and g), not on the shape/width of the container","marks":1}],"section":"practice","hint":{"text":"Look back at Example 4 (Water tank on a stand). Start like this: Formula: ⟪P=\\rho gh⟫","from":4}},{"id":"week04.4.5.p9","kind":"self","q":"Explain why dams are built much thicker at the bottom than at the top.","marks":2,"level":2,"lines":3,"scheme":"Water pressure increases with depth (1), so the force on the bottom of the dam is greatest and it must be strongest there (1).","points":[{"text":"Water pressure increases with depth","marks":1},{"text":"so the force on the bottom of the dam is greatest and it must be strongest there","marks":1}],"section":"practice"}],"exit":[{"id":"week04.4.5.p10","kind":"self","q":"A tank is filled with oil of density 800 kg m^−3^ to a depth of 3.0 m. The base has area 2.0 m^2^. Calculate (a) the pressure due to the oil on the base (b) the force on the base.","marks":4,"level":3,"lines":4,"scheme":"(a) ⟪P=\\rho gh=800\\times 10\\times 3.0⟫ (1) ⟪=24\\,000\\,\\mathrm{Pa}⟫ (1). (b) ⟪F=P\\times A=24\\,000\\times 2.0⟫ (1) ⟪=48\\,000\\,\\mathrm{N}⟫ (1).","points":[{"text":"(a) ⟪P=\\rho gh=800\\times 10\\times 3.0⟫","marks":1},{"text":"⟪=24\\,000\\,\\mathrm{Pa}⟫","marks":1},{"text":"(b) ⟪F=P\\times A=24\\,000\\times 2.0⟫","marks":1},{"text":"⟪=48\\,000\\,\\mathrm{N}⟫","marks":1}],"section":"exit"},{"id":"week04.4.5.p11","kind":"num","q":"In a barometer, atmospheric pressure supports a column of mercury 0.76 m high. Mercury has density 13 600 kg m^−3^. Calculate atmospheric pressure.","marks":3,"level":2,"lines":3,"scheme":"⟪P=\\rho gh=13\\,600\\times 10\\times 0.76⟫ (1) ⟪=103\\,360\\,\\mathrm{Pa}⟫ (1) ≈ ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪P=\\rho gh=13\\,600\\times 10\\times 0.76⟫","marks":1},{"text":"⟪=103\\,360\\,\\mathrm{Pa}⟫","marks":1},{"text":"≈ ⟪1.0\\times 10^{5}\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":100000,"sf":2,"unit":"Pa","unitTex":"\\mathrm{Pa}","alt":[103360]},"section":"exit"}],"warmup":[{"id":"week04.4.5.w1","kind":"self","q":"Define **power** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"The rate of doing work / rate of energy conversion (1); watt, ⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫ (1).","points":[{"text":"The rate of doing work / rate of energy conversion","marks":1},{"text":"watt, ⟪W\\ (=\\mathrm{J}\\,\\mathrm{s}^{-1})⟫","marks":1}],"section":"warmup","src":"week04.4.4.p4"},{"id":"week04.4.5.w2","kind":"self","q":"State the law of conservation of energy.","marks":2,"level":2,"lines":3,"scheme":"Energy cannot be created or destroyed (1), only changed from one form to another (1).","points":[{"text":"Energy cannot be created or destroyed","marks":1},{"text":"only changed from one form to another","marks":1}],"section":"warmup","src":"week04.4.4.p1"},{"id":"week04.4.5.w3","kind":"self","q":"A motor is 75% efficient. Its input power is 400 W. Calculate its useful output power and its wasted power.","marks":2,"level":2,"lines":3,"scheme":"Useful ⟪=0.75\\times 400=300\\,\\mathrm{W}⟫ (1); wasted ⟪=400-300=100\\,\\mathrm{W}⟫ (1).","points":[{"text":"Useful ⟪=0.75\\times 400=300\\,\\mathrm{W}⟫","marks":1},{"text":"wasted ⟪=400-300=100\\,\\mathrm{W}⟫","marks":1}],"section":"warmup","src":"week04.4.4.p8"}],"n":26},{"id":"week04.4.6","kind":"unit","unit":"4.6","title":"Archimedes' Principle, Floating and Sinking","titleText":"Archimedes' Principle, Floating and Sinking","goals":[{"code":"A6.3","text":"Apply Archimedes' principle (upthrust) to explain floating and sinking"}],"codes":["A6.3"],"words":[{"term":"Pressure","def":"Force acting normally per unit area."},{"term":"Upthrust","def":"Upward force of a fluid on an immersed object."},{"term":"Archimedes' principle","def":"Upthrust equals the weight of fluid displaced."},{"term":"Principle of flotation","def":"A floating object displaces its own weight of fluid."}],"learn":{"notes":[{"type":"h","text":"Upthrust"},{"type":"p","text":"Objects feel lighter in water — try lifting a friend in a swimming pool. The water pushes UP on anything placed in it."},{"type":"def","term":"Upthrust","text":"the upward force exerted by a fluid (liquid or gas) on an object that is partly or completely immersed in it."},{"type":"p","text":"**Why is there an upthrust?** Pressure increases with depth. The bottom of an immersed object is deeper than its top, so the water pushes up on the bottom harder than it pushes down on the top. The difference is an overall upward force — the upthrust."},{"type":"def","term":"Archimedes' principle","text":"when an object is wholly or partially immersed in a fluid, it experiences an upthrust equal to the weight of the fluid displaced."},{"type":"formula","tex":"\\text{upthrust }=\\text{ weight of fluid displaced }=\\rho _{\\text{fluid}}\\times V_{\\text{displaced}}\\times g","where":["apparent weight (weight in the fluid) = real weight − upthrust","upthrust = weight in air − weight in liquid  (the 'apparent loss in weight')","V~displaced~ = volume of the part of the object that is under the surface (m^3^)"],"label":"ARCHIMEDES' PRINCIPLE"},{"type":"h","text":"Experiment: verifying Archimedes' principle"},{"type":"img","src":"img/week04/archimedes","alt":"Figure 4.11 — Verifying Archimedes' principle","caption":"Figure 4.11 — Verifying Archimedes' principle","width":5.2,"w":1215,"h":734},{"type":"steps","items":["**Apparatus:** newton-meter (spring balance), a stone or metal block on a thread, displacement (eureka) can, water, small beaker, electronic balance.","Weigh the empty beaker (W~b~).","Hang the object from the newton-meter and record its weight in air, W~1~.","Fill the displacement can with water until it overflows; wait until dripping stops. Place the beaker under the spout.","Lower the object slowly until it is **completely** under water (not touching the sides or bottom). Record the new reading, W~2~.","Weigh the beaker + displaced water, and subtract W~b~ to get the weight of the water displaced.","**Results:** upthrust ⟪=W_{1}-W_{2}⟫. E.g. ⟪5.0\\,\\mathrm{N}-3.0\\,\\mathrm{N}=2.0\\,\\mathrm{N}⟫; the displaced water also weighs 2.0 N.","**Conclusion:** the upthrust equals the weight of water displaced — Archimedes' principle is verified."]},{"type":"bullets","items":["**Precautions:** fill the can until it overflows BEFORE starting; lower the object gently so no water splashes out; the object must not touch the can; read the newton-meter at eye level once it is steady; wipe drops off the spout into the beaker."]},{"type":"h","text":"Floating and sinking"},{"type":"img","src":"img/week04/float_sink","alt":"Figure 4.12 — Comparing weight W and upthrust U","caption":"Figure 4.12 — Comparing weight W and upthrust U","width":6,"w":1400,"h":530},{"type":"table","headers":["Situation","Forces","Density comparison"],"rows":[["Object sinks","weight > maximum upthrust","object denser than the fluid"],["Object rises (when released under the surface)","upthrust > weight","object less dense than the fluid"],["Object floats (at rest at the surface)","upthrust = weight","object (average) density less than the fluid"]]},{"type":"def","term":"Principle of flotation","text":"a floating object displaces its own weight of the fluid in which it floats."},{"type":"h","text":"Applications"},{"type":"bullets","items":["**Ships**: steel is denser than water, so a steel nail sinks. A steel ship is hollow and shaped so it displaces a very large volume of water. The weight of water displaced equals the ship's weight before it is fully submerged, so it floats (its AVERAGE density, including the air inside, is less than water).","**Plimsoll (load) lines**: marks on a ship's side showing safe loading levels. Sea water is denser than fresh (river) water, so a ship floats HIGHER in sea water — it needs to displace a smaller volume to get the same upthrust.","**Submarines**: let water into ballast tanks to increase weight and dive; blow it out with compressed air to rise.","**Hydrometer**: a weighted glass float that measures the density of a liquid (e.g. battery acid, milk). It floats higher in a denser liquid.","**Hot-air balloons**: hot air is less dense than the cool air outside; the upthrust from the air displaced is greater than the total weight, so the balloon rises.","**Life jackets** and fish swim bladders increase volume (and so upthrust) with little extra weight."]},{"type":"remember","text":"Archimedes (Greek, about 287–212 BC) is said to have discovered the principle while taking a bath, when asked to test whether a king's crown was pure gold — the crown's volume, found by displacement, showed its density."},{"type":"warn","text":"Upthrust depends on the volume of fluid DISPLACED (the submerged part) and the density of the FLUID — not on the density of the object, and not on how deep a fully submerged object is."}],"examples":[{"id":"week04.4.6.e1","title":"Upthrust and density of a stone","question":"A stone weighs 12.0 N in air and 7.5 N when completely immersed in water. Calculate (a) the upthrust (b) the volume of the stone (c) the density of the stone. (Density of water ⟪=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫.)","steps":[{"label":"(a) Upthrust","text":"⟪U=12.0-7.5=4.5\\,\\mathrm{N}⟫"},{"label":"(b) Water displaced","text":"weight of water displaced ⟪=4.5\\,\\mathrm{N}⟫ → mass ⟪=4.5\\div 10=0.45\\,\\mathrm{kg}⟫"},{"label":"Volume","text":"⟪V=m\\div \\rho =0.45\\div 1000=4.5\\times 10^{-4}\\,\\mathrm{m}^{3}⟫ (= volume of stone, as it is fully immersed)"},{"label":"(c) Mass of stone","text":"⟪m=W\\div g=12.0\\div 10=1.20\\,\\mathrm{kg}⟫"},{"label":"Density","text":"⟪\\rho =1.20\\div (4.5\\times 10^{-4})=2667\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"}],"answer":"(a) 4.5 N  (b) ⟪4.5\\times 10^{-4}\\,\\mathrm{m}^{3}⟫  (c) ≈ ⟪2.7\\times 10^{3}\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫"},{"id":"week04.4.6.e2","title":"A floating wooden block","question":"A wooden block of volume 0.0020 m^3^ and density 600 kg m^−3^ floats in water. Calculate (a) its weight (b) the upthrust on it (c) the volume of the block under water.","steps":[{"label":"(a) Mass","text":"⟪m=\\rho V=600\\times 0.0020=1.2\\,\\mathrm{kg}⟫;  weight ⟪=1.2\\times 10=12\\,\\mathrm{N}⟫"},{"label":"(b) Floating","text":"floating → upthrust = weight ⟪=12\\,\\mathrm{N}⟫"},{"label":"(c) Water displaced","text":"12 N of water → mass ⟪1.2\\,\\mathrm{kg}\\rightarrow V=1.2\\div 1000=0.0012\\,\\mathrm{m}^{3}⟫"}],"answer":"(a) 12 N  (b) 12 N  (c) 0.0012 m^3^ (60% of the block is under water)"},{"id":"week04.4.6.e3","title":"Will it float?","question":"Which of these will float in water (1000 kg m^−3^)? Ice 920 kg m^−3^, aluminium 2700 kg m^−3^, oak 700 kg m^−3^. (Use the density rule.)","steps":[{"label":"Rule","text":"object floats if its density < density of the liquid"},{"label":"Compare","text":"ice 920 < 1000 ✓;  oak 700 < 1000 ✓;  aluminium 2700 > 1000 ✗"}],"answer":"Ice and oak float; aluminium sinks."}]},"tryit":[{"id":"week04.4.6.p1","kind":"self","q":"Define **upthrust**.","marks":1,"level":1,"lines":2,"scheme":"The upward force exerted by a fluid on an object partly or wholly immersed in it (1).","points":[{"text":"The upward force exerted by a fluid on an object partly or wholly immersed in it","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Upthrust and density of a stone). Start like this: (a) Upthrust: ⟪U=12.0-7.5=4.5\\,\\mathrm{N}⟫","from":1}},{"id":"week04.4.6.p2","kind":"self","q":"State Archimedes' principle.","marks":2,"level":2,"lines":3,"scheme":"When an object is wholly or partially immersed in a fluid it experiences an upthrust (1) equal to the weight of the fluid displaced (1).","points":[{"text":"When an object is wholly or partially immersed in a fluid it experiences an upthrust","marks":1},{"text":"equal to the weight of the fluid displaced","marks":1}],"section":"try"}],"practice":[{"id":"week04.4.6.p3","kind":"self","q":"An object weighs 8.0 N in air and 5.0 N when fully immersed in water. Calculate (a) the upthrust (b) the weight of water displaced.","marks":2,"level":2,"lines":2,"scheme":"(a) ⟪8.0-5.0=3.0\\,\\mathrm{N}⟫ (1). (b) 3.0 N (equal to the upthrust) (1).","points":[{"text":"(a) ⟪8.0-5.0=3.0\\,\\mathrm{N}⟫","marks":1},{"text":"(b) 3.0 N (equal to the upthrust)","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Upthrust and density of a stone). Start like this: (a) Upthrust: ⟪U=12.0-7.5=4.5\\,\\mathrm{N}⟫","from":1}},{"id":"week04.4.6.p4","kind":"self","q":"A cork floats at rest on water. Compare the upthrust on it with its weight.","marks":1,"level":1,"lines":2,"scheme":"They are equal (1).","points":[{"text":"They are equal","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (A floating wooden block). Start like this: (a) Mass: ⟪m=\\rho V=600\\times 0.0020=1.2\\,\\mathrm{kg}⟫;  weight ⟪=1.2\\times 10=12\\,\\mathrm{N}⟫","from":2}},{"id":"week04.4.6.p5","kind":"self","q":"Explain why a steel ship floats but a steel nail sinks.","marks":3,"level":2,"lines":4,"scheme":"The nail is solid steel, denser than water, so its weight is greater than the upthrust (1). The ship is hollow/contains air, so it displaces a much larger volume of water (1); the weight of water displaced (upthrust) equals the ship's weight / its average density is less than water (1).","points":[{"text":"The nail is solid steel, denser than water, so its weight is greater than the upthrust","marks":1},{"text":"The ship is hollow/contains air, so it displaces a much larger volume of water","marks":1},{"text":"the weight of water displaced (upthrust) equals the ship's weight / its average density is less than water","marks":1}],"section":"practice"},{"id":"week04.4.6.p6","kind":"self","q":"A loaded ship sails from a river into the sea. Does it float higher or lower in the water? Explain.","marks":3,"level":2,"lines":4,"scheme":"Higher (1). Sea water is denser than river water (1), so a smaller volume needs to be displaced to give an upthrust equal to the ship's weight (1).","points":[{"text":"Higher","marks":1},{"text":"Sea water is denser than river water","marks":1},{"text":"so a smaller volume needs to be displaced to give an upthrust equal to the ship's weight","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Will it float?). Start like this: Rule: object floats if its density < density of the liquid","from":3}},{"id":"week04.4.6.p7","kind":"self","q":"A metal block of volume ⟪5.0\\times 10^{-4}\\,\\mathrm{m}^{3}⟫ and weight 13 N is fully immersed in water. Calculate (a) the upthrust (b) the reading on a newton-meter holding the block.","marks":3,"level":2,"lines":4,"scheme":"(a) ⟪U=\\rho Vg=1000\\times 5.0\\times 10^{-4}\\times 10⟫ (1) ⟪=5.0\\,\\mathrm{N}⟫ (1). (b) ⟪13-5.0=8.0\\,\\mathrm{N}⟫ (1).","points":[{"text":"(a) ⟪U=\\rho Vg=1000\\times 5.0\\times 10^{-4}\\times 10⟫","marks":1},{"text":"⟪=5.0\\,\\mathrm{N}⟫","marks":1},{"text":"(b) ⟪13-5.0=8.0\\,\\mathrm{N}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (A floating wooden block). Start like this: (a) Mass: ⟪m=\\rho V=600\\times 0.0020=1.2\\,\\mathrm{kg}⟫;  weight ⟪=1.2\\times 10=12\\,\\mathrm{N}⟫","from":2}},{"id":"week04.4.6.p8","kind":"self","q":"Explain, in terms of upthrust, why a hot-air balloon rises.","marks":2,"level":2,"lines":3,"scheme":"The hot air inside is less dense than the surrounding air (1), so the upthrust (weight of cool air displaced) is greater than the total weight of the balloon, and it rises (1).","points":[{"text":"The hot air inside is less dense than the surrounding air","marks":1},{"text":"so the upthrust (weight of cool air displaced) is greater than the total weight of the balloon, and it rises","marks":1}],"section":"practice"}],"exit":[{"id":"week04.4.6.p9","kind":"num","q":"A block of wood of density 500 kg m^−3^ and volume 0.010 m^3^ floats in water. Calculate the volume of the block that is under water.","marks":3,"level":2,"lines":4,"scheme":"Weight ⟪=500\\times 0.010\\times 10=50\\,\\mathrm{N}⟫ (1); floating → upthrust ⟪=50\\,\\mathrm{N}⟫ = weight of water displaced → mass 5.0 kg (1); ⟪V=5.0\\div 1000=0.0050\\,\\mathrm{m}^{3}⟫ (half the block) (1).","points":[{"text":"Weight ⟪=500\\times 0.010\\times 10=50\\,\\mathrm{N}⟫","marks":1},{"text":"floating → upthrust ⟪=50\\,\\mathrm{N}⟫ = weight of water displaced → mass 5.0 kg","marks":1},{"text":"⟪V=5.0\\div 1000=0.0050\\,\\mathrm{m}^{3}⟫ (half the block)","marks":1}],"num":{"value":0.005,"sf":2,"unit":"m^3^","unitTex":"\\mathrm{m}^{3}"},"conf":"low","section":"exit"},{"id":"week04.4.6.p10","kind":"self","q":"Describe an experiment to verify Archimedes' principle. Include the measurements you would take and how you would use them.","marks":5,"level":3,"lines":8,"scheme":"Weigh object in air with newton-meter, W₁ (1); fill displacement can to overflow, beaker under spout (1); lower object fully into water, record W₂ (1); collect and weigh displaced water (beaker + water − empty beaker) (1); compare ⟪W_{1}-W_{2}⟫ (upthrust) with weight of water displaced — they are equal (1).","points":[{"text":"Weigh object in air with newton-meter, W₁","marks":1},{"text":"fill displacement can to overflow, beaker under spout","marks":1},{"text":"lower object fully into water, record W₂","marks":1},{"text":"collect and weigh displaced water (beaker + water − empty beaker)","marks":1},{"text":"compare ⟪W_{1}-W_{2}⟫ (upthrust) with weight of water displaced — they are equal","marks":1}],"section":"exit"}],"warmup":[{"id":"week04.4.6.w1","kind":"self","q":"Explain why a sharp knife cuts better than a blunt one.","marks":2,"level":2,"lines":3,"scheme":"A sharp edge has a very small area (1), so the same force produces a much larger pressure ⟪(P=F/A)⟫ (1).","points":[{"text":"A sharp edge has a very small area","marks":1},{"text":"so the same force produces a much larger pressure ⟪(P=F/A)⟫","marks":1}],"section":"warmup","src":"week04.4.5.p4"},{"id":"week04.4.6.w2","kind":"self","q":"Explain why tractors have wide tyres.","marks":2,"level":2,"lines":3,"scheme":"Wide tyres give a large area (1), so the pressure on the ground is small and the tractor does not sink into soft soil (1).","points":[{"text":"Wide tyres give a large area","marks":1},{"text":"so the pressure on the ground is small and the tractor does not sink into soft soil","marks":1}],"section":"warmup","src":"week04.4.5.p5"},{"id":"week04.4.6.w3","kind":"self","q":"Define **pressure** and state its SI unit.","marks":2,"level":2,"lines":2,"scheme":"Force acting normally/perpendicularly per unit area (1); pascal, ⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫ (1).","points":[{"text":"Force acting normally/perpendicularly per unit area","marks":1},{"text":"pascal, ⟪\\mathrm{Pa}\\ (=\\mathrm{N}\\,\\mathrm{m}^{-2})⟫","marks":1}],"section":"warmup","src":"week04.4.5.p1"}],"n":27},{"id":"week04.check","kind":"check","title":"Book check","titleText":"Book check","check":true,"watchOut":["Squaring ½m as well as v in ⟪E_{k}=\\tfrac{1}{2}mv^{2}⟫ — square ONLY the speed.","Using grams instead of kilograms, or km/h instead of m s^−1^, in energy formulas.","Using weight (N) instead of mass (kg) in mgh, so g is counted twice.","Using the slope length instead of the vertical height for PE or work against gravity.","Calculating efficiency as input ÷ output and getting more than 100%.","Saying energy is 'lost' or 'used up' — it is changed into heat and sound (wasted), never destroyed.","Forgetting to convert minutes to seconds in ⟪P=E/t⟫.","Not converting cm^2^ to m^2^ in ⟪P=F/A⟫ (divide by 10 000, not by 100).","Measuring h in ⟪P=\\rho gh⟫ from the bottom of the container instead of the depth below the surface.","Thinking that upthrust depends on the density of the OBJECT — it depends on the density of the FLUID and the volume displaced."],"mcq":[{"id":"week04.check.m1","kind":"mcq","q":"The SI unit of energy is the","marks":1,"level":1,"options":["watt","joule","newton","pascal"],"answer":"B","explanation":"Energy (and work) is measured in joules. The watt (A) is the unit of POWER — the rate of energy transfer.","section":"p01"},{"id":"week04.check.m2","kind":"mcq","q":"A force of 20 N moves an object 3.0 m in the direction of the force. The work done is","marks":1,"level":1,"options":["6.7 J","23 J","60 J","600 J"],"answer":"C","explanation":"⟪W=F\\times d=20\\times 3.0=60\\,\\mathrm{J}⟫. A is ⟪20\\div 3⟫ (dividing instead of multiplying); B adds the numbers.","section":"p01"},{"id":"week04.check.m3","kind":"mcq","q":"Which energy change takes place in a microphone?","marks":1,"level":1,"options":["electrical → sound","sound → electrical","kinetic → sound","chemical → electrical"],"answer":"B","explanation":"A microphone turns sound into an electrical signal. A is the reverse — that is a loudspeaker.","section":"p01"},{"id":"week04.check.m4","kind":"mcq","q":"Which of the following is a RENEWABLE energy source?","marks":1,"level":1,"options":["coal","natural gas","bagasse (sugar-cane waste)","crude oil"],"answer":"C","explanation":"Bagasse is biomass — new sugar cane is grown every year. Coal, natural gas and oil are fossil fuels that cannot be replaced.","section":"p01"},{"id":"week04.check.m5","kind":"mcq","q":"A 2.0 kg mass moves at 3.0 m s^−1^. Its kinetic energy is","marks":1,"level":1,"options":["3.0 J","6.0 J","9.0 J","18 J"],"answer":"C","explanation":"⟪Ek=\\tfrac{1}{2}\\times 2.0\\times 3.0^{2}=\\tfrac{1}{2}\\times 2.0\\times 9.0=9.0\\,\\mathrm{J}⟫. D (18 J) forgets the ½; B (6.0 J) forgets to square v.","section":"p01"},{"id":"week04.check.m6","kind":"mcq","q":"The speed of a moving car is tripled. Its kinetic energy becomes","marks":1,"level":1,"options":["3 times as large","6 times as large","9 times as large","one-third as large"],"answer":"C","explanation":"⟪Ek\\propto v^{2}⟫, so ⟪3^{2}=9⟫ times. A (3 times) forgets that v is squared.","section":"p01"},{"id":"week04.check.m7","kind":"mcq","q":"A 5.0 kg mass is lifted through 4.0 m. Its gain in gravitational potential energy is ⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫","marks":1,"level":1,"options":["20 J","200 J","2000 J","12.5 J"],"answer":"B","explanation":"⟪mgh=5.0\\times 10\\times 4.0=200\\,\\mathrm{J}⟫. A (20 J) leaves out g.","section":"p01"},{"id":"week04.check.m8","kind":"mcq","q":"A pendulum bob has its MAXIMUM kinetic energy","marks":1,"level":1,"options":["at the highest point of the swing","at the lowest point of the swing","half-way between highest and lowest points","when it stops"],"answer":"B","explanation":"At the lowest point all the GPE (above that level) has become KE, so speed is greatest. At the highest point (A) the bob is momentarily at rest — KE is zero.","section":"p01"},{"id":"week04.check.m9","kind":"mcq","q":"A motor does 1200 J of work in 60 s. Its power is","marks":1,"level":1,"options":["0.05 W","20 W","1260 W","72 000 W"],"answer":"B","explanation":"⟪P=E\\div t=1200\\div 60=20\\,\\mathrm{W}⟫. D multiplies instead of dividing; A divides the wrong way round.","section":"p01"},{"id":"week04.check.m10","kind":"mcq","q":"A machine has an input of 800 J and a useful output of 600 J. Its efficiency is","marks":1,"level":1,"options":["25%","60%","75%","133%"],"answer":"C","explanation":"⟪(600\\div 800)\\times 100\\%=75\\%⟫. A (25%) is the fraction WASTED; D divides input by output — efficiency can never exceed 100%.","section":"p01"},{"id":"week04.check.m11","kind":"mcq","q":"Which of the following would INCREASE the efficiency of a machine?","marks":1,"level":1,"options":["removing the oil from moving parts","lubricating the moving parts","making it work faster","using a heavier load"],"answer":"B","explanation":"Lubrication reduces friction, so less energy is wasted as heat. A would increase friction and lower efficiency.","section":"p01"},{"id":"week04.check.m12","kind":"mcq","q":"A force of 200 N acts on an area of 0.040 m^2^. The pressure is","marks":1,"level":1,"options":["8.0 Pa","200 Pa","800 Pa","5000 Pa"],"answer":"D","explanation":"⟪P=F\\div A=200\\div 0.040=5000\\,\\mathrm{Pa}⟫. A (8.0 Pa) multiplies ⟪F\\times A⟫ instead of dividing.","section":"p01"},{"id":"week04.check.m13","kind":"mcq","q":"The pressure at a point in a liquid does NOT depend on","marks":1,"level":1,"options":["the depth of the point","the density of the liquid","the gravitational field strength","the shape of the container"],"answer":"D","explanation":"⟪P=\\rho gh⟫ — depth, density and g only. Shape and width of the container make no difference.","section":"p01"},{"id":"week04.check.m14","kind":"mcq","q":"What is the pressure due to the water at a depth of 5.0 m in a lake? (⟪\\rho =1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫, ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫)","marks":1,"level":1,"options":["50 Pa","500 Pa","5000 Pa","50 000 Pa"],"answer":"D","explanation":"⟪P=\\rho gh=1000\\times 10\\times 5.0=50\\,000\\,\\mathrm{Pa}⟫. C (5000) leaves out g.","section":"p01"},{"id":"week04.check.m15","kind":"mcq","q":"A stone weighs 10 N in air and 6.0 N when fully immersed in water. The upthrust on the stone is","marks":1,"level":1,"options":["4.0 N","6.0 N","10 N","16 N"],"answer":"A","explanation":"Upthrust = weight in air − weight in water ⟪=10-6.0=4.0\\,\\mathrm{N}⟫. B is just the apparent weight in water.","section":"p01"}],"structured":[{"id":"week04.check.s1","kind":"multi","title":"Energy on a water slide","total":13,"stem":["A child of mass 30 kg starts from rest at the top of a water slide. The top of the slide is 5.0 m vertically above the bottom. ⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫"],"stemBlocks":[],"parts":[{"id":"week04.check.s1.a","kind":"self","q":"State the law of conservation of energy.","marks":2,"level":2,"lines":3,"scheme":"Energy cannot be created or destroyed (1), only changed from one form to another (1).","points":[{"text":"Energy cannot be created or destroyed","marks":1},{"text":"only changed from one form to another","marks":1}],"label":"(a)"},{"id":"week04.check.s1.b","kind":"self","q":"Calculate the gravitational potential energy of the child at the top of the slide, relative to the bottom.","marks":2,"level":2,"lines":2,"scheme":"⟪Ep=mgh=30\\times 10\\times 5.0⟫ (1) ⟪=1500\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪Ep=mgh=30\\times 10\\times 5.0⟫","marks":1},{"text":"⟪=1500\\,\\mathrm{J}⟫","marks":1}],"num":{"value":1500,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(b)","autoKind":"num"},{"id":"week04.check.s1.c","kind":"self","q":"Assuming no energy is lost, calculate the speed of the child at the bottom of the slide.","marks":3,"level":2,"lines":4,"scheme":"KE at bottom ⟪=1500\\,\\mathrm{J}⟫ (1); ⟪v^{2}=2\\times 1500\\div 30=100⟫ (1); ⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫ (1).","points":[{"text":"KE at bottom ⟪=1500\\,\\mathrm{J}⟫","marks":1},{"text":"⟪v^{2}=2\\times 1500\\div 30=100⟫","marks":1},{"text":"⟪v=10\\,\\mathrm{m}\\,\\mathrm{s}^{-1}⟫","marks":1}],"num":{"value":10,"sf":1,"unit":"m s^−1^","unitTex":"\\mathrm{m}\\,\\mathrm{s}^{-1}"},"conf":"low","label":"(c)","autoKind":"num"},{"id":"week04.check.s1.d","kind":"self","q":"The child's actual speed at the bottom is 8.0 m s^−1^. Calculate the actual kinetic energy and the energy lost.","marks":3,"level":2,"lines":4,"scheme":"⟪KE=\\tfrac{1}{2}\\times 30\\times 8.0^{2}=960\\,\\mathrm{J}\\ (1)⟫(1); energy lost ⟪=1500-960=540\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪KE=\\tfrac{1}{2}\\times 30\\times 8.0^{2}=960\\,\\mathrm{J}⟫","marks":2},{"text":"energy lost ⟪=1500-960=540\\,\\mathrm{J}⟫","marks":1}],"label":"(d)"},{"id":"week04.check.s1.e","kind":"self","q":"State what happens to the 'lost' energy, and calculate the efficiency with which PE is changed into KE.","marks":3,"level":2,"lines":4,"scheme":"Changed to heat (thermal energy) and sound by friction with the slide/water and air resistance (1); efficiency ⟪=(960\\div 1500)\\times 100\\%⟫ (1) ⟪=64\\%⟫ (1).","points":[{"text":"Changed to heat (thermal energy) and sound by friction with the slide/water and air resistance","marks":1},{"text":"efficiency ⟪=(960\\div 1500)\\times 100\\%⟫","marks":1},{"text":"⟪=64\\%⟫","marks":1}],"label":"(e)"}]},{"id":"week04.check.s2","kind":"multi","title":"Pumping water to a roof tank","total":12,"stem":["An electric pump lifts water from a well into a tank on a roof. The water is raised through a vertical height of 12 m. The pump lifts 150 kg of water in 2.0 minutes. The electrical input power of the pump is 250 W."],"stemBlocks":[],"parts":[{"id":"week04.check.s2.a","kind":"self","q":"Define **power**.","marks":1,"level":1,"lines":2,"scheme":"The rate of doing work / rate of energy conversion (1).","points":[{"text":"The rate of doing work / rate of energy conversion","marks":1}],"label":"(a)"},{"id":"week04.check.s2.b","kind":"self","q":"Calculate the work done in lifting the water.","marks":2,"level":2,"lines":3,"scheme":"⟪W=mgh=150\\times 10\\times 12⟫ (1) ⟪=18\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪W=mgh=150\\times 10\\times 12⟫","marks":1},{"text":"⟪=18\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":18000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(b)","autoKind":"num"},{"id":"week04.check.s2.c","kind":"self","q":"Calculate the useful output power of the pump.","marks":2,"level":2,"lines":3,"scheme":"⟪t=2.0\\times 60=120\\,\\mathrm{s}⟫ (1); ⟪P=18\\,000\\div 120=150\\,\\mathrm{W}⟫ (1).","points":[{"text":"⟪t=2.0\\times 60=120\\,\\mathrm{s}⟫","marks":1},{"text":"⟪P=18\\,000\\div 120=150\\,\\mathrm{W}⟫","marks":1}],"num":{"value":150,"sf":2,"unit":"W","unitTex":"\\mathrm{W}"},"label":"(c)","autoKind":"num"},{"id":"week04.check.s2.d","kind":"self","q":"Calculate the efficiency of the pump.","marks":2,"level":2,"lines":3,"scheme":"⟪(150\\div 250)\\times 100\\%⟫ (1) ⟪=60\\%⟫ (1).","points":[{"text":"⟪(150\\div 250)\\times 100\\%⟫","marks":1},{"text":"⟪=60\\%⟫","marks":1}],"num":{"value":60,"sf":1,"unit":"%","unitTex":"\\%"},"label":"(d)","autoKind":"num"},{"id":"week04.check.s2.e","kind":"self","q":"Give TWO reasons why the efficiency of the pump is less than 100%.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): friction in moving parts → heat; heating of the motor's wires (resistance); sound/vibration; friction between water and pipes.","points":[{"text":"Any two (1 each): friction in moving parts → heat; heating of the motor's wires (resistance); sound/vibration; friction between water and pipes.","marks":2,"each":true}],"label":"(e)"},{"id":"week04.check.s2.f","kind":"self","q":"The water surface in the tank is 12 m above a tap at ground level. Calculate the water pressure at the tap, and explain why tanks are placed high above the taps.","marks":3,"level":2,"lines":4,"scheme":"⟪P=\\rho gh=1000\\times 10\\times 12⟫ (1) ⟪=120\\,000\\,\\mathrm{Pa}\\ (1.2\\times 10^{5}\\,\\mathrm{Pa})⟫ (1); pressure increases with height of water above the tap, so water flows out faster (1).","points":[{"text":"⟪P=\\rho gh=1000\\times 10\\times 12⟫","marks":1},{"text":"⟪=120\\,000\\,\\mathrm{Pa}\\ (1.2\\times 10^{5}\\,\\mathrm{Pa})⟫","marks":1},{"text":"pressure increases with height of water above the tap, so water flows out faster","marks":1}],"label":"(f)"}]},{"id":"week04.check.s3","kind":"multi","title":"A floating wooden block","total":12,"stem":["A rectangular wooden block measures ⟪0.20\\,\\mathrm{m}\\times 0.10\\,\\mathrm{m}\\times 0.050\\,\\mathrm{m}⟫. The density of the wood is 800 kg m^−3^. (Density of water ⟪=1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫, ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫.)"],"stemBlocks":[],"parts":[{"id":"week04.check.s3.a","kind":"self","q":"Define **pressure**.","marks":1,"level":1,"lines":2,"scheme":"Force acting normally per unit area (1).","points":[{"text":"Force acting normally per unit area","marks":1}],"label":"(a)"},{"id":"week04.check.s3.b","kind":"self","q":"Calculate the volume, mass and weight of the block.","marks":3,"level":2,"lines":4,"scheme":"⟪V=0.20\\times 0.10\\times 0.050=1.0\\times 10^{-3}\\,\\mathrm{m}^{3}⟫ (1); ⟪m=\\rho V=800\\times 1.0\\times 10^{-3}=0.80\\,\\mathrm{kg}⟫ (1); ⟪W=0.80\\times 10=8.0\\,\\mathrm{N}⟫ (1).","points":[{"text":"⟪V=0.20\\times 0.10\\times 0.050=1.0\\times 10^{-3}\\,\\mathrm{m}^{3}⟫","marks":1},{"text":"⟪m=\\rho V=800\\times 1.0\\times 10^{-3}=0.80\\,\\mathrm{kg}⟫","marks":1},{"text":"⟪W=0.80\\times 10=8.0\\,\\mathrm{N}⟫","marks":1}],"label":"(b)"},{"id":"week04.check.s3.c","kind":"self","q":"Calculate the pressure the block exerts on a table when it rests on its largest face.","marks":2,"level":2,"lines":3,"scheme":"⟪A=0.20\\times 0.10=0.020\\,\\mathrm{m}^{2}⟫ (1); ⟪P=8.0\\div 0.020=400\\,\\mathrm{Pa}⟫ (1).","points":[{"text":"⟪A=0.20\\times 0.10=0.020\\,\\mathrm{m}^{2}⟫","marks":1},{"text":"⟪P=8.0\\div 0.020=400\\,\\mathrm{Pa}⟫","marks":1}],"num":{"value":400,"sf":1,"unit":"Pa","unitTex":"\\mathrm{Pa}"},"label":"(c)","autoKind":"num"},{"id":"week04.check.s3.d","kind":"self","q":"State Archimedes' principle.","marks":2,"level":2,"lines":3,"scheme":"An object wholly or partly immersed in a fluid experiences an upthrust (1) equal to the weight of fluid displaced (1).","points":[{"text":"An object wholly or partly immersed in a fluid experiences an upthrust","marks":1},{"text":"equal to the weight of fluid displaced","marks":1}],"label":"(d)"},{"id":"week04.check.s3.e","kind":"self","q":"The block is placed in water. Explain why it floats, and state the upthrust on it when it floats at rest.","marks":2,"level":2,"lines":3,"scheme":"Its density (800 kg m⁻³) is less than that of water (1); upthrust = weight ⟪=8.0\\,\\mathrm{N}⟫ (1).","points":[{"text":"Its density (800 kg m⁻³) is less than that of water","marks":1},{"text":"upthrust = weight ⟪=8.0\\,\\mathrm{N}⟫","marks":1}],"label":"(e)"},{"id":"week04.check.s3.f","kind":"self","q":"The block floats with its largest face horizontal. Calculate the volume of water displaced and how deep the bottom of the block is below the water surface.","marks":2,"level":2,"lines":4,"scheme":"⟪V=8.0\\div (1000\\times 10)=8.0\\times 10^{-4}\\,\\mathrm{m}^{3}⟫ (1); depth ⟪=8.0\\times 10^{-4}\\div 0.020=0.040\\,\\mathrm{m}=4.0\\,\\mathrm{cm}⟫ (1).","points":[{"text":"⟪V=8.0\\div (1000\\times 10)=8.0\\times 10^{-4}\\,\\mathrm{m}^{3}⟫","marks":1},{"text":"depth ⟪=8.0\\times 10^{-4}\\div 0.020=0.040\\,\\mathrm{m}=4.0\\,\\mathrm{cm}⟫","marks":1}],"label":"(f)"}]}],"n":28},{"id":"week04.past","kind":"past","title":"Past-paper practice","titleText":"Past-paper practice","check":true,"log":true,"questions":[{"id":"week04.past.q1","kind":"multi","title":"Data analysis: pressure and depth (Paper 02 Question 1 style)","total":25,"stem":["A student used a pressure sensor to measure the pressure, p, due to a salt solution at different depths, h, below its surface. Her results are shown in the table below.","⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫"],"stemBlocks":[{"type":"table","headers":["Depth, h / m","0.00","0.10","0.20","0.30","0.40","0.50","0.60"],"rows":[["Pressure, p / kPa","0.0","1.1","2.3","3.2","3.6","5.5","6.6"]]}],"parts":[{"id":"week04.past.q1.a","kind":"self","q":"On the grid provided, plot a graph of pressure, p (y-axis), against depth, h (x-axis). Draw the line of best fit.","marks":7,"level":3,"img":{"src":"img/week04/graph_paper","alt":"On the grid provided, plot a graph of pressure, p (y-axis), against depth, h (x-axis). Draw the line of best fit.","w":1174,"h":894},"lines":0,"scheme":"Axes labelled with quantity and unit ⟪(1+1)⟫; suitable scale using more than half the grid, e.g. 0.1 m and 1 kPa per big square (1); all 7 points plotted correctly (2, −1 per error); single ruled best-fit line through the origin, IGNORING the point at 0.40 m (1); title, e.g. 'Graph of p against h' (1).","points":[{"text":"Axes labelled with quantity and unit","marks":2},{"text":"suitable scale using more than half the grid, e.g. 0.1 m and 1 kPa per big square","marks":1},{"text":"all 7 points plotted correctly (2, −1 per error); single ruled best-fit line through the origin, IGNORING the point at 0.40 m","marks":1},{"text":"title, e.g. 'Graph of p against h'","marks":1}],"conf":"low","label":"(a)","grid":true},{"id":"week04.past.q1.b","kind":"self","q":"One result is anomalous. Identify it and suggest ONE reason for it.","marks":2,"level":2,"lines":3,"scheme":"⟪h=0.40\\,\\mathrm{m}⟫, ⟪p=3.6\\,\\mathrm{kPa}⟫ (should be about 4.4 kPa) (1); e.g. sensor not lowered to the full 0.40 m / depth misread / reading taken before sensor settled (1).","points":[{"text":"⟪h=0.40\\,\\mathrm{m}⟫, ⟪p=3.6\\,\\mathrm{kPa}⟫ (should be about 4.4 kPa)","marks":1},{"text":"e.g. sensor not lowered to the full 0.40 m / depth misread / reading taken before sensor settled","marks":1}],"label":"(b)"},{"id":"week04.past.q1.c","kind":"self","q":"Determine the gradient of your graph. Show clearly the triangle you used.","marks":4,"level":3,"lines":4,"scheme":"Large triangle shown on graph (1); correct Δp and Δh read from the line (1); gradient ≈ 11 kPa m⁻¹ (accept 10.5–11.5) (1); correct unit kPa m⁻¹ (1).","points":[{"text":"Large triangle shown on graph","marks":1},{"text":"correct Δp and Δh read from the line","marks":1},{"text":"gradient ≈ 11 kPa m⁻¹ (accept 10.5–11.5)","marks":1},{"text":"correct unit kPa m⁻¹","marks":1}],"label":"(c)"},{"id":"week04.past.q1.d","kind":"self","q":"Given that ⟪p=\\rho gh⟫, use your gradient to calculate the density, ρ, of the salt solution.","marks":3,"level":2,"lines":4,"scheme":"Gradient ⟪=\\rho g⟫ (1); convert: ⟪11\\,\\mathrm{kPa}\\,\\mathrm{m}^{-1}=11\\,000\\,\\mathrm{Pa}\\,\\mathrm{m}^{-1}⟫ (1); ⟪\\rho =11\\,000\\div 10=1100\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (accept 1050–1150, e.c.f. from gradient) (1).","points":[{"text":"Gradient ⟪=\\rho g⟫","marks":1},{"text":"convert: ⟪11\\,\\mathrm{kPa}\\,\\mathrm{m}^{-1}=11\\,000\\,\\mathrm{Pa}\\,\\mathrm{m}^{-1}⟫","marks":1},{"text":"⟪\\rho =11\\,000\\div 10=1100\\,\\mathrm{kg}\\,\\mathrm{m}^{-3}⟫ (accept 1050–1150, e.c.f. from gradient)","marks":1}],"num":{"value":1100,"sf":2,"unit":"kg m^−3^","unitTex":"\\mathrm{kg}\\,\\mathrm{m}^{-3}","min":1050,"max":1150},"label":"(d)","autoKind":"num"},{"id":"week04.past.q1.e","kind":"self","q":"Use your graph to find the pressure at a depth of 0.35 m. Show on the graph how you obtained your answer.","marks":2,"level":2,"lines":2,"scheme":"Dashed construction lines from 0.35 m to the line and across to the p-axis (1); ⟪p\\approx 3.85\\,\\mathrm{kPa}⟫ (accept 3.7–4.0) (1).","points":[{"text":"Dashed construction lines from 0.35 m to the line and across to the p-axis","marks":1},{"text":"⟪p\\approx 3.85\\,\\mathrm{kPa}⟫ (accept 3.7–4.0)","marks":1}],"num":{"value":3.85,"sf":3,"unit":"kPa","unitTex":"\\mathrm{kPa}","min":3.7,"max":4},"label":"(e)","autoKind":"num"},{"id":"week04.past.q1.f","kind":"self","q":"State the relationship between p and h shown by your graph. Give a reason.","marks":2,"level":2,"lines":2,"scheme":"p is directly proportional to h (1); the graph is a straight line through the origin (1).","points":[{"text":"p is directly proportional to h","marks":1},{"text":"the graph is a straight line through the origin","marks":1}],"label":"(f)"},{"id":"week04.past.q1.g","kind":"self","q":"The experiment is repeated with pure water ⟪(\\rho =1000\\,\\mathrm{kg}\\,\\mathrm{m}^{-3})⟫. Calculate the pressure at a depth of 0.30 m and state how the new line would compare with the first.","marks":3,"level":2,"lines":4,"scheme":"⟪p=1000\\times 10\\times 0.30⟫ (1) ⟪=3000\\,\\mathrm{Pa}=3.0\\,\\mathrm{kPa}⟫ (1); the line would be less steep (smaller gradient) — still through the origin (1).","points":[{"text":"⟪p=1000\\times 10\\times 0.30⟫","marks":1},{"text":"⟪=3000\\,\\mathrm{Pa}=3.0\\,\\mathrm{kPa}⟫","marks":1},{"text":"the line would be less steep (smaller gradient) — still through the origin","marks":1}],"label":"(g)"},{"id":"week04.past.q1.h","kind":"self","q":"Atmospheric pressure is 101 kPa. Calculate the TOTAL pressure at a depth of 0.60 m in the salt solution.","marks":2,"level":2,"lines":2,"scheme":"Total ⟪=101+6.6⟫ (1) ⟪=107.6\\,\\mathrm{kPa}\\approx 108\\,\\mathrm{kPa}⟫ (1).","points":[{"text":"Total ⟪=101+6.6⟫","marks":1},{"text":"⟪=107.6\\,\\mathrm{kPa}\\approx 108\\,\\mathrm{kPa}⟫","marks":1}],"num":{"value":108,"sf":3,"unit":"kPa","unitTex":"\\mathrm{kPa}","alt":[107.6]},"label":"(h)","autoKind":"num"}]},{"id":"week04.past.q2","kind":"multi","title":"Extended response: energy for the Caribbean","total":15,"stem":["Many Caribbean countries spend large sums of money importing oil to generate electricity."],"stemBlocks":[],"parts":[{"id":"week04.past.q2.a","kind":"self","q":"(i) Distinguish between renewable and non-renewable energy sources.  (ii) Explain TWO reasons why Caribbean territories should develop renewable energy sources.","marks":6,"level":3,"lines":7,"scheme":"(i) Renewable: naturally replenished/will not run out, e.g. solar (1); non-renewable: will be used up/cannot be replaced in a human lifetime, e.g. oil (1). (ii) Two explained reasons, 2 marks each: e.g. reduces cost of oil imports (1) saving foreign exchange/lower electricity bills (1); reduces CO₂ emissions (1) and so climate change, to which small islands are very vulnerable (sea-level rise/hurricanes) (1); the region has abundant sunshine/trade winds/geothermal heat (1) so the resource is free and available (1); energy security (1) — less affected by world oil price rises (1).","points":[{"text":"(i) Renewable: naturally replenished/will not run out, e.g. solar","marks":1},{"text":"non-renewable: will be used up/cannot be replaced in a human lifetime, e.g. oil","marks":1},{"text":"(ii) Two explained reasons, 2 marks each: e.g. reduces cost of oil imports","marks":1},{"text":"saving foreign exchange/lower electricity bills","marks":1},{"text":"reduces CO₂ emissions","marks":1},{"text":"and so climate change, to which small islands are very vulnerable (sea-level rise/hurricanes)","marks":1},{"text":"the region has abundant sunshine/trade winds/geothermal heat","marks":1},{"text":"so the resource is free and available","marks":1},{"text":"energy security","marks":1},{"text":"— less affected by world oil price rises","marks":1}],"conf":"low","label":"(a)"},{"id":"week04.past.q2.b","kind":"self","q":"In a small hydroelectric plant, 500 kg of water falls through a vertical height of 40 m every second. Calculate the gravitational potential energy lost by the water each second, and hence the power available.","marks":3,"level":2,"lines":4,"scheme":"⟪Ep=mgh=500\\times 10\\times 40⟫ (1) ⟪=200\\,000\\,\\mathrm{J}⟫ each second (1); power ⟪=200\\,000\\,\\mathrm{W}=200\\,\\mathrm{kW}⟫ (1).","points":[{"text":"⟪Ep=mgh=500\\times 10\\times 40⟫","marks":1},{"text":"⟪=200\\,000\\,\\mathrm{J}⟫ each second","marks":1},{"text":"power ⟪=200\\,000\\,\\mathrm{W}=200\\,\\mathrm{kW}⟫","marks":1}],"label":"(b)"},{"id":"week04.past.q2.c","kind":"self","q":"The electrical power output of the plant is 150 kW. Calculate the efficiency of the plant.","marks":2,"level":2,"lines":3,"scheme":"⟪(150\\div 200)\\times 100\\%⟫ (1) ⟪=75\\%⟫ (1).","points":[{"text":"⟪(150\\div 200)\\times 100\\%⟫","marks":1},{"text":"⟪=75\\%⟫","marks":1}],"num":{"value":75,"sf":2,"unit":"%","unitTex":"\\%"},"label":"(c)","autoKind":"num"},{"id":"week04.past.q2.d","kind":"self","q":"State the energy changes that take place in the hydroelectric plant.","marks":2,"level":2,"lines":2,"scheme":"GPE of water → KE of water/turbine (1) → electrical energy (1).","points":[{"text":"GPE of water → KE of water/turbine","marks":1},{"text":"→ electrical energy","marks":1}],"label":"(d)"},{"id":"week04.past.q2.e","kind":"self","q":"Suggest why hydroelectric power is suitable for Dominica but not for Antigua.","marks":2,"level":2,"lines":3,"scheme":"Dominica is mountainous with many fast-flowing rivers/high rainfall (1); Antigua is low-lying/flat with few rivers and less rain (1).","points":[{"text":"Dominica is mountainous with many fast-flowing rivers/high rainfall","marks":1},{"text":"Antigua is low-lying/flat with few rivers and less rain","marks":1}],"label":"(e)"}]}],"n":29}]};
